    'cli.doctor.mode_split' => 'mode {tui} dans le TUI, {headless} pour -p, {background} pour les démons lancés (valeurs par défaut intégrées)',
    'cli.doctor.no_problems' => 'Aucun problème détecté.',
    'cli.doctor.pdo' => 'pdo_{driver} {state} ; ext-sqlite3 {sqlite3} — la liste de tâches Team ouvre SQLite3 directement',
    'cli.doctor.pdo_unusable' => 'INUTILISABLE — le magasin de sessions ne peut pas ouvrir sa base de données : {error}',
