    'cli.doctor.php_too_old' => '{version} à {binary} (candy-code nécessite PHP 8.3+)',
    'cli.doctor.provider' => '{provider} (modèle {model})',
    'cli.doctor.provider_none' => 'aucun sélectionné — le backend écho hors ligne répondra (définir CANDY_CODE_PROVIDER)',
    'cli.doctor.provider_shell' => 'backend shell (niveau $CANDY_CODE_BACKEND_CMD)',
    'cli.doctor.provider_unconstructable' => '{provider} sélectionné mais impossible à construire : {error}',
    'cli.doctor.provider_unknown' => '{provider} sélectionné mais fournisseur inconnu — voir `candy-code models`',
    'cli.doctor.sandbox_binary' => '{backend} à {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} introuvable dans PATH',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" configuré mais bubblewrap est réservé à Linux et cet hôte est {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox désactivé ; bubblewrap est réservé à Linux et cet hôte est {os}',
    'cli.doctor.sandbox_off' => 'bashSandbox désactivé ; {bwrap}, et le bac à sable démarrerait ici s\'il était activé',
    'cli.doctor.sandbox_off_blocked' => 'bashSandbox désactivé ; {bwrap}, et le bac à sable ne démarrerait pas ici même activé ({reason})',
    'cli.doctor.sandbox_ready' => 'bashSandbox "{mode}" ; {bwrap}, et le bac à sable démarre',
    'cli.doctor.sandbox_refused' => 'bashSandbox "{mode}" configuré mais le bac à sable ne démarre pas ({reason}) — {remedy}',
    'cli.doctor.sandbox_remedy_apparmor' => 'installer bubblewrap, ou ajouter un profil /etc/apparmor.d accordant à bwrap les espaces de noms utilisateur non privilégiés (le sysctl apparmor_restrict_unprivileged_userns est le repli grossier)',
    'cli.doctor.sandbox_remedy_generic' => 'installer bubblewrap, ou définir bashSandbox sur "off"',
    'cli.doctor.sandbox_remedy_seatbelt' => 'vérifier que /usr/bin/sandbox-exec fonctionne encore sur cette installation macOS, ou définir bashSandbox sur "off"',
    'cli.doctor.server_ready' => 'pcntl, posix et ffi disponibles — `serve` peut démarrer',
    'cli.doctor.server_refuses' => '`serve` refusera de démarrer : {problems}',
    'cli.doctor.sessions' => '{count} session(s) stockée(s)',
    'cli.doctor.settings_clean' => 'chaque fichier de paramètres ne contient que des clés lues par candy-code',
    'cli.doctor.unknown' => 'inconnu',
    'cli.headless.permission_hint' => '  astuce : un lancement `-p` sans mode nommé démarre en mode `default` avec questions ; les demandes sans surveillance n\'ont personne pour répondre, elles échouent donc en mode fermé. Les lancements scriptés peuvent spécifier --permission-mode bypass-permissions (ou accept-edits) pour continuer.',
    'cli.help.screen' => <<<'TXT'
CandyCode — assistant de codage IA pour le terminal.

Utilisation :
  candy-code                       Démarrer le TUI interactif (par défaut)
  candy-code <dir>                 Démarrer le TUI enraciné dans <dir>, qui doit
                                   exister (uniquement comme premier argument)
  candy-code [<dir>] <words…>      Démarrer le TUI et envoyer les mots comme
                                   premier prompt, ex. candy-code fix the bug
  candy-code -c                    Continuer la session la plus récente
  candy-code --resume [<id>]       Reprendre une session stockée (sélecteur si pas d'id)
  candy-code -p <prompt>           Exécuter un seul prompt et quitter (one-shot)
  candy-code run "<prompt>"        Alias de -p "<prompt>" (mode one-shot)
  candy-code --output-format json  Sortie JSON lisible par machine (one-shot)
  candy-code --worktree [<name>]   Exécuter cette session dans un worktree git
                                   dédié (créé s'il n'existe pas)

Sous-commandes (aucune n'ouvre le TUI ni ne nécessite un fournisseur, une clé API ou un
terminal ; chacune répond et quitte sauf serve et mcp serve, qui tournent jusqu'à
arrêt — et attach, qui est l'exception aux deux : il exécute le TUI sur la session d'un serveur en cours
d'exécution ; acp exécute des tours pour un éditeur, jusqu'à la déconnexion de l'éditeur) :
  bundles list           Lister les bundles de plugins visibles depuis ce répertoire : nom,
                         version, niveau, et les surfaces portées par chacun —
                         y compris les hooks et .mcp.json que candy-code
                         refuse d'exécuter.
  bundles install <src>  Copier un répertoire de bundle, ou cloner une URL git avec un
                         clone borné de profondeur un, dans le répertoire racine des bundles
                         utilisateur (~/.candy-code/bundles), où seul vous en êtes propriétaire.
  doctor                 Vérifier cette installation et signaler tout problème
                         détecté : version PHP, extensions requises par le magasin de sessions
                         et serve, fichier de configuration, politique de
                         permissions, fournisseur sélectionné, base de données des sessions
                         et configuration MCP du projet. Quitte avec 1 si une vérification
                         ÉCHEOUE.
                         Distinct de l'outil "doctor" appelable par le modèle, qui
                         signale le protocole d'images du terminal au modèle.
  import claude          Prévisualise l'import des paramètres Claude Code : lit le fichier
                         de paramètres utilisateur de Claude, plus le fichier .claude sous la
                         racine de lancement quand --project est précisé, traduit ses listes
                         allow/deny/ask en permissionRules (le côté le plus strict
                         gagne toujours — deny l'emporte sur allow), mappe le modèle, et
                         nomme toute clé sans destination comme ignorée. Rien n'est écrit tant
                         que ce n'est pas confirmé : --yes accepte l'aperçu imprimé tel quel,
                         sinon un terminal interactif est sollicité. L'aperçu nomme
                         chaque règle allow qui élargirait ce qui s'exécute sans demande.
  login <provider>       Connecte un fournisseur : claude-code et codex passent la
                         main au terminal à leur propre CLI (le jeton ne transite
                         jamais par candy-code) ; openai, anthropic et gemini
                         collent une clé dans le bloc providers du fichier de
                         configuration ; les autres nomment le vrai détenteur de leur identifiant.
  models                 Liste les fournisseurs sélectionnables par cette installation et le
                         modèle par défaut de chacun ; "*" marque le fournisseur
                         sélectionné.
  session list [--all|--archived|--children] [--limit N]
                         Liste les sessions stockées, épinglées d'abord puis les plus
                         récentes : id, dernière mise à jour, type, tours,
                         fournisseur/modèle et nom (★ marque une ligne épinglée).
                         --children ajoute les lignes sous-agent et arrière-plan,
                         --archived ajoute les archivées, --all ajoute les deux ;
                         20 lignes sauf si --limit en décide autrement.
  session show <target>  Affiche les détails et la transcription d'une session.
  session rename <target> <title…>
                         Renomme une session ; les mots après la cible forment
                         le titre.
  session delete <target> [--with-children]
                         Supprime une session. Les enfants sous-agent partent avec elle ;
                         les branches sont conservées sauf avec --with-children.
  session pin|unpin|archive|unarchive <target>
                         Épingle une session (listée en premier, jamais purgée), ou
                         l'archive (masquée de la liste par défaut, conservée).
                         <target> est un id, un nom ou un préfixe d'id unique.
                         Quitte avec 1 si rien ne correspond, 2 si un préfixe est
                         ambigu (les candidats sont listés).
  mcp list               Liste les serveurs MCP déclarés dans .mcp.json, SANS
                         en démarrer aucun. Signale plutôt quand le fichier
                         est absent, se résout hors de l'arborescence du projet, ou est
                         présent mais que la racine du projet n'est pas approuvée.
  mcp trust              Approuve le .mcp.json de ce projet en l'état : ajoute
                         la racine à "trustedProjectMcp" et enregistre la commande,
                         les args et l'env de chaque serveur, afin qu'une modification
                         ultérieure de l'un d'eux soit refusée au lancement tant qu'il
                         n'est pas réapprouvé. Ne démarre rien.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Traduit une config MCP étrangère et imprime le bloc
                         .mcp.json équivalent sur stdout. N'imprime que par
                         défaut ; --write user ajoute les entrées traduites
                         dans le ~/.candy-code/mcp.json de l'utilisateur
                         (une collision de noms refuse l'écriture entière, et le
                         niveau projet n'est jamais écrit). Les renommages
                         effectués par la traduction sont listés sur stderr.
  mcp serve [--root PATH]
                         Sert candy-code lui-même comme serveur MCP sur stdio :
                         une trame JSON-RPC par ligne en entrée, une réponse par ligne
                         en sortie, jusqu'à la fermeture de stdin. Les appels d'outils
                         exécutent le roster en lecture seule (Read, Glob, Grep, Ls,
                         RepoMap), confiné à la racine du workspace, via le PermissionGate
                         du lancement et la chaîne de hooks PreToolUse — c'est le serveur
                         MCP qu'un client peut engendrer ; le WebSocket
                         `candy-code serve` ne parle toujours pas MCP. S'exécute jusqu'à
                         l'arrêt.
  lsp install <language> Installe le serveur de langage épinglé pour un
                         langage : le paquet npm ou le binaire de release vérifié par
                         checksum, dans la racine d'installation privée sous
                         votre home. `lsp list` indique quels langages sont
                         installables.
  lsp list               Signale chaque langage installable : sa version épinglée,
                         l'emplacement d'installation de son serveur (ou son absence),
                         et si une release existe pour le système d'exploitation
                         et l'architecture de cette machine. Ne démarre rien,
                         ne télécharge rien.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Remplace cette installation phar par la dernière release
                         candy-code publiée, vérifiée sha256 contre le sidecar
                         de release AVANT le remplacement ; le phar en cours est
                         conservé en <phar>.old et --rollback restaure exactement
                         cette copie une fois. Quand une clé publique de signature est
                         épinglée dans la source de release, la signature
                         candy-code.phar.minisig doit aussi vérifier (--allow-unsigned
                         ne saute que cette étape). --check rapporte seulement
                         l'actuel vs la dernière et quitte avec 1 quand une mise à jour
                         est disponible. Une installation Composer est refusée
                         bruyamment, en nommant la commande composer update à lancer
                         à la place. Une installation dev-built suit la release
                         rolling candy-code/dev par défaut (elle est à jour quand le
                         commit cible de la release correspond au sha du stamp) et
                         --channel sélectionne explicitement l'un des deux trains.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Lance le serveur WebSocket + HTTP utilisé par l'interface web,
                         au premier plan jusqu'à Ctrl+C. Écoute sur 127.0.0.1:7420
                         par défaut et affiche une URL de connexion dont le … à usage unique
                         le code est échangé contre un cookie de navigateur ; chaque client
                         en a besoin ou le jeton dans ~/.candy-code/server/token,
                         loopback inclus. Options :
      --host <ip>        Adresse de liaison (par défaut 127.0.0.1 ; localhost et ::1
                         comptent aussi comme boucle locale). Toute autre adresse est refusée
                         sauf si --allow-remote est également fourni.
      --port <n>         Port de liaison (par défaut 7420 ; 0 en choisit un libre).
      --allow-remote     Autoriser un --host hors boucle locale. Sans --tls-cert et
                         --tls-key, c'est du HTTP en clair : placez un proxy inverse TLS
                         devant, ou servez TLS directement (voir ci-dessous). Sur
                         0.0.0.0 ou ::, le serveur répond aux propres adresses
                         de cette machine, et l'URL de connexion les nomme.
      --tls-cert <file>  Certificat PEM avec lequel l'écouteur sert TLS lui-même,
                         fourni avec --tls-key. L'URL de connexion
                         commence par https://, le cookie de session porte Secure,
                         et un client http:// en clair ne reçoit aucune réponse.
      --tls-key <file>   Clé privée PEM pour --tls-cert : un fichier lisible sans
                         bits groupe ni monde ouverts, correspondant au certificat.
                         Une paire invalide ou incomplète est refusée au démarrage.
      --allowed-host <list>
                         Noms d'hôte supplémentaires séparés par des virgules (ou host:port) auxquels
                         le serveur répond, p. ex. un nom DNS pour cette machine.
                         Répétable.
      --allowed-ips <list>
                         IPs de clients ou plages CIDR séparées par des virgules (p. ex.
                         1.2.3.4,10.0.0.0/8) autorisées à se connecter ; toute autre
                         adresse reçoit un 403 avant la connexion. La boucle locale est
                         toujours autorisée. Non défini : aucun filtre d'adresse.
                         Répétable.
      --allowed-origin <list>
                         Origines de navigateur supplémentaires séparées par des virgules
                         (http(s)://host[:port]) autorisées en plus de celles du
                         serveur. Répétable.
      --allow-dir-browse Permettre aux clients connectés de choisir le répertoire où une nouvelle session
                         démarre : ils peuvent lister les noms de répertoires (jamais
                         de fichiers) sous --browse-root. Désactivé par défaut.
      --browse-root <dir>
                         Le répertoire auquel --allow-dir-browse est limité
                         (par défaut votre répertoire personnel).
      --web-root <dir>   Servir l'interface web depuis <dir> au lieu du paquet
                         sugarcraft/candy-code-web installé.
      --no-web           Servir uniquement l'API et WebSocket, sans fichiers d'interface.
      --allow-bypass     Permettre aux sessions de tourner en bypass-permissions ou dont-ask
                         (refusé par défaut ; les sessions du serveur démarrent en
                         mode par défaut sauf si --permission-mode indique le contraire).
      --allow-root       Autoriser l'exécution en tant que root (refusé par défaut).
      --detach           Exécuter en arrière-plan : afficher l'URL et le pid une fois
                         le port lié, puis quitter ; le serveur journalise dans
                         server.log dans son répertoire d'état.
      --parent-pid <pid> Arrêter le serveur quand le processus <pid> se termine (pour un
                         éditeur ou TUI qui démarre un serveur privé).
                         Refuse de démarrer sans ext-pcntl, ext-posix et
                         ext-ffi (voir doctor). Quitte avec 1 si le port est pris ou
                         un serveur tourne déjà depuis le même répertoire d'état.
  serve status           Signaler le serveur en cours : pid, URL, racine, durée de fonctionnement et
                         si GET /api/health répond. Quitte avec 1 quand aucun
                         ne tourne.
  serve stop [--force]   L'arrêter : SIGTERM, jusqu'à 30 s pour drainer, puis SIGKILL.
      --force            SIGKILL immédiatement.
  serve logs [-f]        Afficher la fin du journal d'un serveur détaché.
  -f, --follow           Continuer à afficher ce qu'il ajoute jusqu'à son arrêt.
  serve url [--qr]       Afficher une URL de connexion avec un nouveau code à usage unique.
      --qr              Afficher chaque URL de connexion sous forme de code QR terminal scannable.
  serve token [--rotate] Afficher le jeton propriétaire envoyé par les clients bearer.
      --rotate           Le remplacer ; un serveur en cours garde l'ancien jusqu'à
                         son redémarrage.
  attach [<session>] [--url <url>]
                         Exécuter le TUI sur une session d'un candy-code
                         serve en cours : le serveur exécute chaque tour et ses outils, et
                         ce terminal les affiche et répond aux questions
                         de permission qu'ils posent. <session> est un id, un nom ou un
                         préfixe d'id unique d'une des sessions du serveur ;
                         sans lui, une nouvelle est créée. Le serveur est celui
                         que serve status signale, son jeton pris de
                         CANDY_CODE_SERVER_TOKEN ou du fichier de jeton du
                         répertoire d'état. Quitter détache ; un tour en cours
                         continue. Quitte avec 1 si aucun serveur ne répond.
      --url <url>        Se connecter au serveur à <url> (l'adresse que serve
                         affiche) à la place.
  acp                    Exécuter comme agent Agent Client Protocol : l'éditeur
                         (Zed, JetBrains, Neovim) le démarre et communique
                         en JSON-RPC sur son stdin et stdout. Les sessions s'ouvrent dans
                         la racine du projet de l'éditeur, les tours s'exécutent ici avec
                         le fournisseur et les outils de cette installation, et l'éditeur répond
                         à leurs questions de permission. Non destiné à un terminal : stdout
                         ne transporte que le protocole (tout le reste va vers
                         stderr). Quitte avec 0 quand l'éditeur ferme stdin.
  completion bash|zsh|fish
                         Écrit un script de complétion shell sur stdout, ex.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Agrège le registre de dépenses persistant par jour et par modèle :
                         la même page que `/usage` affiche, sur le même repli
                         partagé. 7 et 30 prennent des jours UTC entiers, aujourd'hui inclus,
                         all (ou aucun opérande) couvre tout le registre, et une
                         fenêtre hors de cet ensemble est refusée plutôt que
                         silencieusement élargie. --session restreint à une session
                         par id, nom ou préfixe unique ; --output-format json
                         émet la carte des faits dont la page est issue. Un
                         registre illisible indique sa raison et quitte avec 1 ;
                         les dollars pour les replis incluant un modèle non tarifé
                         s'affichent comme une borne inférieure ≥, jamais comme une simple somme.

Options :
  -p, --prompt <text>    Fournit un prompt en ligne de commande (mode one-shot)
      --output-format <format>
                         Format de sortie : "text" (par défaut), "json" ou
                         "stream-json" (événements NDJSON, réponse en dernier)
      --root <dir>       Utilise <dir> comme racine du projet au lieu du répertoire
                         courant. Accepte aussi --root=<dir> (la forme à utiliser
                         quand <dir> commence par "-") ; il ne peut être omis.
                         Nommer une racine ici ET comme argument positionnel est
                         refusé plutôt que d'en laisser un gagner silencieusement.
      --config <file>    Lit les paramètres, permissions et racines de hooks fiables depuis
                         <file> au lieu de ~/.candy-code/config.json. Accepte
                         aussi --config=<file>. Doit déjà exister, être
                         lisible, vous appartenir, et ni lui ni son
                         répertoire ne doivent être accessibles en écriture à tous — il porte la
                         politique de permissions, donc il est soumis au même standard
                         que ~/.candy-code/config.json (un fichier sous /etc ou
                         /tmp est normalement refusé pour l'une de ces raisons).
                         Seul le FICHIER se déplace : agents, skills, workflows,
                         sessions et mémoire restent dans ~/.candy-code.
      --model <name>     Utilise <name> comme modèle de conversation, écrasant
                         $CANDY_CODE_MODEL et le défaut propre au fournisseur. Accepte
                         aussi --model=<name>. Sélectionne un modèle, pas un fournisseur
                         — le fournisseur vient toujours de $CANDY_CODE_PROVIDER ou
                         du paramètre `provider` persisté, et les deux sont
                         des axes indépendants.
      --permission-mode <mode>
                         Exécute sous <mode> au lieu du mode du fichier de
                         configuration. Accepte aussi --permission-mode=<mode>. Priorité
                         la plus élevée : il l'emporte sur $CANDY_CODE_PERMISSION_MODE et
                         la clé permissionMode de la configuration. L'un de : default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Sans aucune valeur définie, le TUI et -p
                         démarrent en default (il demande avant les écritures et les commandes
                         shell) ; seul un daemon lancé localement démarre en
                         bypass-permissions.
      --max-cost <usd>   Plafonne ce lancement à <usd> dollars US de dépenses
                         rapportées : le tour qui franchirait le plafond est
                         refusé et non envoyé. Accepte aussi --max-cost=<usd>.
                         Priorité la plus élevée : il l'emporte sur $CANDY_CODE_MAX_COST et
                         la clé maxCostUsd de la configuration. Décimal autorisé, un
                         $ initial accepté ($2.50) ; zéro et négatif sont
                         refusés plutôt que lus comme "pas de plafond". /budget
                         relève ou efface le plafond pour la session en cours.
      --max-turns <n>    Plafonne ce lancement à <n> étapes de boucle d'outils : le tour
                         qui les utilise toutes s'arrête où il en est et le signale.
                         Accepte aussi --max-turns=<n>. Priorité la plus élevée :
                         il l'emporte sur la clé maxToolSteps (cet axe
                         n'a pas de variable d'environnement). Un entier positif
                         ; zéro est refusé plutôt que lu comme "pas
                         de plafond", et une valeur inutilisable refuse le lancement
                         plutôt que de se soumettre silencieusement au paramètre.
      --json-schema <path-or-json>
                         Contraint la réponse à un JSON Schema : un document
                         {"type":"object",...} en ligne ou un chemin vers un fichier
                         en contenant un. Accepte aussi --json-schema=<value> ;
                         la forme = est celle à utiliser quand le chemin commence
                         par "-". Seuls les fournisseurs déclarant prendre en charge
                         les réponses contraintes par schéma exécutent la requête —
                         tout autre refuse avec exit 2 plutôt que
                         facturer une réponse non contrainte. Le schéma
                         conditionne la requête d'auto-achèvement du tour ; les étapes
                         qui continuent une boucle d'outils restent libres (une
                         réponse JSON forcée ne peut porter d'appels d'outils).
      --append-system-prompt <text-or-@file>
                         Ajoute des règles d'opérateur au prompt système de ce
                         lancement : texte en ligne, ou @chemin vers un fichier
                         contenant. Accepte aussi --append-system-prompt=<value> ;
                         la forme = est celle à utiliser quand le chemin commence
                         avec « - ». Les règles arrivent comme un bloc
                         d'instructions personnelles délimité, jamais une
                         substitution : elles ne peuvent ni remplacer ni
                         déclasser les couches supérieures, et les marqueurs
                         de bloc forgés dans le texte sont neutralisés.
                         Limité à la même taille qu'un document d'instructions.
                         Uniquement avec -p ou le verbe run : un lancement
                         sans prompt auquel ajouter les règles refuse avec
                         le code de sortie 2 plutôt que de les ignorer
                         silencieusement.
  -c, --continue         Rouvrir la dernière session utilisée, transcript
                         et tout le reste, au lieu d'en démarrer une nouvelle. Sans
                         cette option, chaque lancement ouvre une nouvelle session ;
                         Flèche haut dans une zone de saisie vide rappelle quand même
                         name (voir `session list`). Sans valeur, ouvrir le
      --resume [<id|name>]
                         Rouvrir une session stockée par id, préfixe d'id unique ou
                         la réponse est enregistrée dans la ligne). Accepte également
                         sélecteur de session au lancement ; avec -p une cible est
                         OBLIGATOIRE (le transcript amorce l'appel one-shot et la
                         réponse est sauvegardée dans la ligne). Accepte aussi
                         --resume=<id>. Non combinable avec --continue.
      --worktree [<name>]
                         Exécuter toute la session dans un git worktree
                         main-<name> sur la branche candy-code/<name>, créé
                         au premier usage ; sans nom, le worktree reçoit un
                         en dehors d'une arborescence de travail git et à côté de `serve`.
                         commit ni modification est supprimé ; un worktree avec
                         du travail reste et annonce son chemin. Refusé
                         Ce que l'exécution a produit ne réside que dans le processus ;
      --incognito        Lancement qui ne conserve rien : aucune ligne de session,
                         aucun transcript, aucune écriture automatique en mémoire
                         à la fin du tour. Ce que le run a produit ne vit que dans
                         le processus ; les sessions et notes stockées
                         ANTÉRIEUREMENT restent lisibles. Refusé avec --continue
                         ou --resume, qui rouvrent des sessions conservées.
      --restricted       Lancement qui ne peut pas exécuter de code : Bash,
                         PtyRun, Task, Workflow, ShellStop et mcp_call sont retirés
                         de tout ensemble exposé au modèle pour toute la session,
                         et /permissions ne peut pas les rétablir. Les outils de
                         fichiers restent, sous le confinement de chemin existant.
                         Accepte aussi --restricted=true|false, pour qu'un wrapper
                         puisse surclasser un alias portant l'option sans valeur.
                         Survit au redémarrage.
      --safe-mode        Lancement qui ignore toute confiance : chaque racine
                         de projet approuvée répond non approuvée (hooks, MCP
                         projet et shells de commandes), aucun bundle ne se charge,
                         et aucune compétence, commande ou agent externe n'est
                         découvert. Paramètres, compétences et commandes natifs
                         restent. Accepte aussi --safe-mode=true|false pour
                         surclasser un alias. Survit au redémarrage.
  -h, --help             Afficher ce message d'aide
  -v, --version          Afficher la version installée et quitter
      --                 Fin des options : tout argument suivant est positionnel,
                         jamais une option
   CANDY_CODE_MODEL       Nom du modèle (remplace le défaut du fournisseur ; --model gagne)
Variables d'environnement :
   CANDY_CODE_PROVIDER    Fournisseur à utiliser : openai, anthropic, claude-code,
                          sglang, bedrock, vertex, custom
   CANDY_CODE_MODEL       Nom du modèle (remplace la valeur par défaut du fournisseur ; --model a priorité)
   CANDY_CODE_PERMISSION_MODE
                          Mode de permission initial, remplaçant la clé de
                          configuration permissionMode (--permission-mode a priorité)
   CANDY_CODE_BACKEND_CMD Commande shell pour un adaptateur de backend personnalisé, selon le
                          contrat PROSE : reçoit l'historique JSON sur stdin, écrit
                          le texte de réponse sur stdout, utilisé tel quel
                          (tronqué uniquement aux deux extrémités, chaque saut de ligne, ligne
                          vide et indentation interne est préservé).
   CANDY_CODE_BACKEND_CMD_STREAM
                          Le même appel shell selon l'autre contrat, un flux
                          TOKEN : un token par ligne, le saut de ligne entre deux
                          tokens est un délimiteur et est ignoré, et une ligne VIDE est
                          un saut de ligne littéral dans la réponse. Le callback se
                          déclenche par token à mesure que la commande les produit, mais
                          la boucle de lecture est synchrone, l'écran se rafraîchit une
                          fois à la fin plutôt que token par token. Non interchangeable
                          avec CANDY_CODE_BACKEND_CMD dans un sens comme dans l'autre — un
                          wrapper prose exécuté via cette variable revient sans aucun
                          saut de ligne et chaque ligne vide réduite à une seule.
                          CANDY_CODE_BACKEND_CMD a priorité quand les deux sont définis.
                          Pour les deux, non défini, vide et uniquement des espaces
                          comptent comme absent.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Exécuter les appels d'outils d'un tour strictement un par un.
                          L'exécution concurrente est le comportement par défaut et ne
                          regroupe que les outils non mutatifs ; c'est la solution de repli.
                          Persister sous "parallelToolCalls": false dans
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Secondes pendant lesquelles un groupe concurrent peut s'exécuter
                          puis la valeur par défaut. Une valeur hors de 1-119, ou une valeur qui
                          n'est pas un nombre du tout, ne compte pas comme définie — elle
                          passe à la source suivante plutôt que de
                          l'ignorer.
   CANDY_CODE_ADVISOR_MODEL
                          Le modèle que l'outil `Advisor` consulte pour un second
                          avis : une complétion sans outil, facturée comme
                          tout autre appel. Contrairement à CANDY_CODE_TITLE_MODEL, il
                          n'y a pas de repli économique — non défini signifie que l'outil
                          n'est pas proposé du tout. Lu au lancement.
   CANDY_CODE_TITLE_MODEL Le modèle économique utilisé pour nommer automatiquement une session après
                          son premier échange ; par défaut celui du fournisseur.
   CANDY_CODE_SUMMARY_MODEL
                          Le modèle qui rédige les résumés de compaction ;
                          par défaut celui de la conversation, qui réutilise
                          le cache de prompt.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual ou off : comment une session élagage son
                          contexte quand /pruning n'a pas choisi (par défaut auto).
   CANDY_CODE_MAX_COST    Un plafond de dépenses pour ce lancement, en dollars US
                          (décimal autorisé ; un "$" initial est accepté ;
                          --max-cost a priorité). Un tour qui dépasse le plafond
                          est refusé.
   CANDY_CODE_CONNECT_TIMEOUT
                          Limite de la phase de connexion, en secondes (décimal
                          autorisé ; par défaut 15.0), pour les transports HTTP
                          du fournisseur. Elle borne l'établissement de la connexion
                          uniquement — ce n'est pas un délai d'expiration total de la requête. Le temps
                          qu'un serveur de streaming connecté peut prendre pour envoyer ses
                          en-têtes de réponse est réglé par le paramètre distinct
                          streamHeaderTimeoutSeconds.
   CANDY_CODE_SEARCH_ENDPOINT
                          API de recherche interrogée par l'outil WebSearch intégré.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Un nombre entier positif de jours : chaque lancement supprime
                          les sessions non touchées depuis au moins cette durée.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Hôte d'envoi retiré : /share n'envoie jamais
                          nulle part. Quand défini, l'export local est toujours
                          écrit et la réponse refuse bruyamment la clé et mentionne
                          /share serve, qui publie une page d'instantané auto-hébergée
                          sur votre propre candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Répertoire de base sous lequel les worktrees git
                          par coéquipier sont créés.
   CANDY_CODE_DISABLE_MOUSE
                          Toute valeur autre que vide ou 0 désactive entièrement le
                          suivi de la souris.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Toute valeur autre que vide ou 0 ignore les gestes de
                          clic tout en conservant le défilement à la molette.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Toute valeur autre que vide ou 0 désactive les points
                          de rupture du cache de prompt du fournisseur.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Toute valeur autre que vide ou 0 désactive la suggestion
                          de message suivant grisée (→ l'accepte) après chaque tour.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Toute valeur autre que vide ou 0 désactive la sauvegarde
                          automatique de faits durables en notes après un tour, et
                          le passage de consolidation repliant le journal de
                          compaction dans celles-ci.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Toute valeur autre que vide ou 0 désactive la lecture et
                          l'actualisation de la base de données de modèles LiteLLM qui dimensionne et
                          tarifie les modèles sans valeur intégrée.
   CANDY_CODE_NO_UPDATE_CHECK
                          Toute valeur autre que vide ou 0 désactive la vérification quotidienne des
                          versions phar et la notification de mise à jour au démarrage qu'elle alimente ;
                          aucune requête ne quitte le processus et une notification
                          obsolète en cache n'est plus affichée.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Toute valeur autre que vide ou 0 exclut la carte des
                          symètres classés du prompt système.
   CANDY_CODE_BACKGROUND  light ou dark — force ce que le thème adaptatif
                          estime du fond du terminal, en ignorant
                          la sonde OSC 11 et COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Toute valeur autre que vide ou 0 remet les lignes
                          par-omission et par-répertoire-refusé de SkillLoader sur
                          stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Toute valeur autre que vide ou 0 remet les lignes de
                          refus de découverte de CommandLoader sur stderr.
   CANDY_CODE_DEBUG_RULES Toute valeur autre que vide ou 0 remet les lignes de
                          refus de découverte de RuleLoader sur stderr.
   CANDY_CODE_DEBUG_STREAM
                          Toute valeur autre que vide ou 0 conserve la ligne
                          "onToken observer threw" de Chat sur stderr. Le
                          détachement lui-même a lieu dans les deux cas.
   CANDY_CODE_SERVER_HOST L'adresse sur laquelle `serve` s'attache (--host a priorité).
   CANDY_CODE_SERVER_PORT Le port sur lequel `serve` s'attache (--port a priorité).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Origines supplémentaires séparées par des virgules que `serve` accepte
                          (--allowed-origin a priorité).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Noms d'hôte supplémentaires séparés par des virgules auxquels `serve` répond
                          (--allowed-host a priorité).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          IPs ou CIDRs de clients séparés par des virgules que `serve` admet
                          en plus de la boucle locale (--allowed-ips a priorité).
   CANDY_CODE_SERVER_WEB_ROOT
                          Répertoire depuis lequel `serve` sert l'interface web (--web-root
                          a priorité).
   CANDY_CODE_SERVER_TOKEN
                          Le jeton requis par `serve`, en remplacement de celui dans
                          son répertoire d'état (au moins 32 caractères ; pour
                          les conteneurs).
   CANDY_CODE_SERVER_DIR  Le répertoire où `serve` conserve son jeton, verrou,
                          enregistrement de découverte et journal (par défaut
                          ~/.candy-code/server ; créé en 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Un processus avec lequel `serve` s'arrête (--parent-pid a priorité).
   CANDY_CODE_MCP_DISABLE
                          1, true ou yes (insensible à la casse) désactive le MCP
                          projet entièrement : .mcp.json est traité comme absent, aucun
                          serveur ne démarre. Non défini, 0 ou toute autre valeur maintient
                          MCP activé — contrairement aux variables de type drapeau,
                          seuls ces trois mots sont pris en compte.
   CANDY_CODE_QUIET_LOGS  1, true ou yes (insensible à la casse) réduit au silence le
                          canal parallèle error_log() à l'échelle du processus sur son unique
                          destinataire ; non défini, 0 ou toute autre valeur maintient les
                          diagnostics actifs. Uniquement au lancement, aucune clé de configuration.
   CANDY_CODE_REDUCED_MOTION
                          1, true ou yes (insensible à la casse) fige le spinner de l'agent
                          sur une seule image statique — pour les utilisateurs sensibles au
                          mouvement et préférence de mouvement réduit. Lu une seule fois au lancement ;
                          aucune clé de configuration.
   CANDY_CODE_SD_BASE_URL URL de base du serveur Stable Diffusion de style
                          A1111 (sdapi) que le transport multimédia contacte.
                          Ordre de priorité : un remplacement explicite dans le code, puis cette
                          variable, puis le paramètre sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Comment les images générées sont affichées dans le terminal
                          (la couche env du paramètre ui.imageRenderMode ; voir
                          docs/ENVIRONMENT.md pour les valeurs acceptées).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Définir à 1 exactement pour autoriser la SUITE DE TESTS candy-code
                          à s'exécuter en tant que root ; non défini ou toute autre valeur, la suite
                          refuse de se lancer avec euid 0. Rien concernant un
                          lancement candy-code ne change — la suite n'est pas une
                          interface destinée à l'utilisateur.
   CANDY_CODE_TOOL_INPUT  La carte complète des arguments de l'appel d'outil
                          script utilisateur courant, encodée en JSON, exportée dans le processus
                          enfant de chaque exécution d'un outil ~/.candy-code/tools ;
                          l'application y écrit, ne la relit jamais, et
                          personne ne la définit manuellement.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Nombre de spans transportés par un lot d'export OTLP
                          (par défaut 64, borné à 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Durée maximale en secondes de chaque tentative d'export OTLP
                          (par défaut 3 ; une valeur non positive ou malformée
                          revient à la valeur par défaut).

   docs/ENVIRONMENT.md recense toutes les variables lues par cette compilation, avec leur
   contrat complet.

Codes de sortie (mode one-shot et chaque sous-commande) :
  0                      Le prompt a été exécuté et a produit une réponse, ou la
                         sous-commande a répondu
  1                      Exécuté et échoué : le backend a levé une erreur (hôte inaccessible,
                         clé rejetée, erreur de modèle) — une nouvelle tentative peut aider — ou une
                         sous-commande a été exécutée et a échoué (un contrôle doctor a retourné
                         FAIL, un verbe `session` n'a trouvé aucune session, un
                         .mcp.json approuvé n'a pas pu être analysé)
  2                      Erreur d'utilisation ou de configuration, rien n'a été tenté
                         et une nouvelle tentative n'aidera pas : aucun prompt fourni, un
                         drapeau non reconnu, un argument nu qui ne nomme aucun
                         répertoire existant (un prompt nécessite -p), un --root
                         ne nommant aucun répertoire, un autoload.php de composer
                         manquant, ou un fournisseur sélectionné
                         qui ne peut pas être construit — soit
                         $CANDY_CODE_PROVIDER ou le fournisseur persisté dans
                         ~/.candy-code/config.json par Ctrl+P "Switch model".
                         Une exécution one-shot ne bascule jamais sur le fournisseur echo
                         hors ligne lorsqu'un fournisseur a été explicitement sélectionné.
                         Une sous-commande recevant un opérande manquant ou inconnu
                         (`session`, `mcp bogus`, `completion tcsh`) renvoie
                         ici aussi.
  130/143/129             TUI : un signal a arrêté la boucle — 128+N pour
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP ; une sortie coopérative
                         (/exit, q) quitte toujours avec 0.

Exemples :
  candy-code -p "Expliquer la différence entre require et include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Écrire un hello world en Go"
  candy-code run "Écrire un hello world en Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Pour plus d'informations, voir le README :
  https://github.com/detain/sugarcraft/tree/master/candy-code

