    'cli.permission.question' => 'un appel d\'outil nécessite votre permission.',
    'cli.permission.refused' => '{tool} refusé.',
    'cli.permission.stdin_ended' => 'stdin s\'est terminé avant la réponse à la question — refus de {tool}.',
    'cli.permission.unrenderable_arguments' => '<arguments impossibles à afficher>',
    'cli.references.missing' => 'l\'entrée `references` {path} n\'est pas un répertoire existant, Read, Grep, Glob et Ls ne la consulteront donc pas.',
    'cli.references.redundant' => 'l\'entrée `references` {path} se trouve dans l\'espace de travail de session — la prison le couvre déjà, il n\'est donc pas ajouté comme seconde racine de lecture.',
    'cli.references.unusable' => 'une entrée `references` n\'a pas pu être lue — elle doit être un objet avec un `path` (ou une chaîne de chemin simple) ; cette entrée a été ignorée.',
    'cli.refuse.bad_mode' => '{source} est \'{value}\', qui n\'est pas un mode de permission (attendu : l\'un de {valid}). Refus de démarrer plutôt que de recourir au défaut permissif.',
    'cli.refuse.claude_mcp_arg_entry' => 'claudeMcpArgs contient une entrée non scalaire ; chaînes argv uniquement',
    'cli.refuse.claude_mcp_args' => 'claudeMcpArgs doit être un tableau JSON de scalaires dans la configuration utilisateur',
    'cli.refuse.claude_mcp_binary' => 'claudeMcpBinary doit être un chemin en chaîne dans la configuration utilisateur',
    'cli.refuse.claude_mcp_env' => 'claudeMcpEnv doit être un objet JSON dans la configuration utilisateur',
    'cli.refuse.claude_mcp_env_entry' => 'claudeMcpEnv doit mapper des clés chaîne vers des valeurs chaîne',
    'cli.refuse.config_bom' => 'il commence par une marque d\'ordre d\'octets UTF-8, que JSON n\'autorise pas — réenregistrez le fichier en UTF-8 sans BOM',
    'cli.refuse.config_dangling' => '{path} existe mais n\'est pas un fichier lisible (c\'est un lien symbolique qui ne pointe vers aucun). Refus de démarrer plutôt que d\'exécuter avec une politique de permission inconnue.',
    'cli.refuse.config_is_directory' => '{path} existe mais n\'est pas un fichier lisible (c\'est un répertoire). Refus de démarrer plutôt que d\'exécuter avec une politique de permission inconnue.',
    'cli.refuse.config_not_json' => '{path} n\'est pas un JSON utilisable ({error}). Refus de démarrer plutôt que d\'exécuter avec une politique de permission inconnue.',
    'cli.refuse.config_not_object' => 'le niveau supérieur n\'est pas un objet JSON',
    'cli.refuse.config_unreachable' => '{path} est inaccessible : {reason}, il est donc impossible de savoir si une politique de permissions y est configurée. Refus de démarrer plutôt que de fonctionner avec une politique de permissions inconnue.',
    'cli.refuse.config_unreadable' => '{path} existe mais n\'a pas pu être lu (vérifiez ses permissions). Refus de démarrer plutôt que de fonctionner avec une politique de permissions inconnue.',
    'cli.refuse.dangling_directory' => '{dir} est un lien symbolique qui ne résout pas vers un répertoire que ce processus peut parcourir',
    'cli.refuse.foreign_owner' => '{path} appartient à l\'uid {uid}, et non au compte sous lequel cette session s\'exécute ; la politique de permissions et la chaîne de hooks qu\'il porte appartiennent à quelqu\'un d\'autre. Refus de démarrer plutôt que de fonctionner avec la politique d\'un autre compte.',
    'cli.refuse.hook_chain' => '{error} Refus de démarrer plutôt que de fonctionner avec une chaîne de hooks qui n\'est pas celle configurée.',
    'cli.refuse.hooks_unreachable' => '{path} est inaccessible : {reason}, il est donc impossible de savoir si des hooks y sont configurés. Refus de démarrer plutôt que de fonctionner avec une chaîne de hooks inconnue.',
    'cli.refuse.keybindings' => 'le paramètre keybindings est inutilisable : {reason}. Supprimez la clé pour utiliser les raccourcis fournis (la référence /keys les nomme). Refus de démarrer plutôt que de fonctionner avec des remplacements de raccourcis que vous n\'avez pas demandés.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST vaut « {value} », ce qui n\'est pas un plafond de dépenses. Un nombre positif de dollars US est attendu (décimal autorisé, un $ initial accepté), par exemple 5 ou $2.50. Zéro et les valeurs négatives sont refusés plutôt que lus comme « pas de plafond » car ils expriment la demande inverse ; une valeur trop grande pour être représentée (1e309, c\'est-à-dire l\'infini) est refusée car elle installerait un plafond qui ne se déclenche jamais. Désactivez la variable pour ne pas imposer de plafond. Refus de démarrer plutôt que de fonctionner sans plafond avec un plafond que vous avez demandé.',
    'cli.refuse.max_cost_flag' => '--max-cost vaut « {value} », ce qui n\'est pas un plafond de dépenses. Un nombre positif de dollars US est attendu (décimal autorisé, un $ initial accepté), par exemple 5 ou $2.50. Zéro et les valeurs négatives sont refusés plutôt que lus comme « pas de plafond » car ils expriment la demande inverse ; une valeur trop grande pour être représentée (1e309, c\'est-à-dire l\'infini) est refusée car elle installerait un plafond qui ne se déclenche jamais. Retirez le drapeau pour ne pas imposer de plafond. Refus de démarrer plutôt que de fonctionner sans plafond avec un plafond que vous avez demandé.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd dans vos paramètres vaut {value}, ce qui n\'est pas un plafond de dépenses. Un nombre positif de dollars US est attendu, par exemple 5 ou 2.5. Supprimez la clé pour ne pas imposer de plafond. Refus de démarrer plutôt que de fonctionner sans plafond avec un plafond que vous avez demandé.',
    'cli.refuse.max_turns_flag' => '--max-turns vaut « {value} », ce qui n\'est pas un plafond d\'étapes. Un nombre entier positif d\'étapes de boucle d\'outils est attendu, par exemple 8. Zéro est refusé plutôt que lu comme « pas de plafond » car il exprime la demande inverse ; une valeur trop grande pour être représentée est refusée car elle installerait un plafond qui ne se déclenche jamais. Retirez le drapeau pour déléguer au paramètre maxToolSteps. Refus de démarrer plutôt que de fonctionner sans plafond avec un plafond que vous avez demandé.',
    'cli.refuse.no_home' => 'ce processus ne peut pas déterminer quel répertoire personnel est le vôtre ($HOME non défini, $USERPROFILE non défini, et aucune entrée passwd pour son uid), la politique de permissions et la chaîne de hooks dans ~/.candy-code ne peuvent donc pas être localisées. Refus de démarrer plutôt que de lire l\'une ou l\'autre dans un répertoire de repli accessible en écriture à tous — exportez HOME vers le compte auquel cette session appartient.',
    'cli.refuse.no_project_root' => 'impossible de déterminer une racine de projet — le répertoire de travail du processus est indisponible (supprimé ou illisible). Passez --root <dir>.',
    'cli.refuse.not_searchable' => '{dir} n\'est pas parcourable par ce processus',
    'cli.refuse.project_settings_unusable' => '{path} n\'a pas pu être lu pour ses permissionRules ({reason}). Refus de démarrer plutôt que de fonctionner avec une politique de permissions inconnue.',
    'cli.refuse.world_writable' => '{path} est accessible en écriture à tous les comptes de cette machine ; la politique de permissions et la chaîne de hooks qu\'il porte ne sont donc pas celles de cet utilisateur. Refus de démarrer plutôt que de fonctionner avec une politique que n\'importe qui aurait pu écrire — `chmod o-w {path}`.',
    'cli.selfupdate.channel_invalid' => '{value} : candy-code self-update --channel accepte stable ou dev.',
    'cli.selfupdate.check_available' => 'candy-code : mise à jour disponible — cette installation est {current}, la dernière version est {latest}. (--check signale uniquement ; rien n\'a été installé.)',
    'cli.selfupdate.check_unknown' => 'candy-code : impossible de comparer cette installation ({current}) à la dernière version ({latest}).',
    'cli.selfupdate.check_up_to_date' => 'candy-code : à jour — cette installation est {current}, la dernière version est {latest}.',
    'cli.selfupdate.composer_mode' => 'candy-code : self-update remplace une installation phar, et cette copie a été installée via Composer — il n\'y a pas de phar ici à échanger. Mettez-la à jour avec : {command} (une installation globale exécute `composer global update sugarcraft/candy-code` à la place).',
    'cli.selfupdate.composer_mode_root' => 'candy-code : self-update remplace une installation phar, et cette copie est le paquet sugarcraft/candy-code installé comme racine Composer — il n\'y a pas de phar ici à échanger, et un paquet racine ne peut pas se rafraîchir via sa propre commande de dépendance. Mettez-le à jour avec : {command} (le clone récupère la nouvelle source, puis reconstruit l\'arborescence vendor).',
    'cli.selfupdate.dir_not_writable' => 'candy-code : impossible de remplacer le phar — le répertoire {dir} n\'est pas accessible en écriture.',
    'cli.selfupdate.downgrade_refused' => 'candy-code : refus de rétrograder — cette installation est {current}, la dernière version est {latest}. (--rollback restaure la copie conservée ; rien d\'autre ne recule.)',
    'cli.selfupdate.download_failed' => 'candy-code : impossible de télécharger {asset} : {reason}',
    'cli.selfupdate.empty_download' => 'candy-code : le téléchargement de {asset} n\'a produit aucun octet.',
    'cli.selfupdate.fetch_failed' => 'candy-code : impossible de lire la liste des versions : {reason}',
    'cli.selfupdate.flags_exclusive' => '--check signale uniquement ; passez-le seul, pas avec --rollback ou --allow-unsigned.',
    'cli.selfupdate.hash_mismatch' => 'candy-code : le phar téléchargé a pour empreinte {actual}, et non {expected} que le sidecar signe. Rien n\'a été échangé.',
    'cli.selfupdate.hash_unreadable' => 'rien (le fichier temporaire n\'a pas pu être lu)',
    'cli.selfupdate.installed' => 'candy-code : self-update a remplacé {path} ({from} -> {to}) ; le phar précédent est conservé à {old} — `self-update --rollback` le restaure une fois.',
    'cli.selfupdate.no_dev_release' => 'candy-code : aucune version dev publiée (tag {tag}) ne porte à la fois {phar} et {sidecar}.',
    'cli.selfupdate.no_release' => 'candy-code : aucune version candy-code publiée ne porte à la fois {phar} et {sidecar}.',
    'cli.selfupdate.phar_not_writable' => 'candy-code : impossible de remplacer le phar — {path} n\'est pas accessible en écriture.',
    'cli.selfupdate.preserve_failed' => 'candy-code : le phar en cours d\'exécution n\'a pas pu être copié vers {old} ; rien n\'a été échangé.',
    'cli.selfupdate.rename_failed' => 'candy-code : le phar vérifié n\'a pas pu être déplacé en place ; la copie en cours d\'exécution est intacte et la copie conservée reste à {old}.',
    'cli.selfupdate.rollback_failed' => 'candy-code : impossible de restaurer {old} par-dessus {path}.',
    'cli.selfupdate.rollback_missing' => 'candy-code : aucune copie conservée à restaurer : {old} n\'existe pas (elle n\'apparaît qu\'après une mise à jour réussie).',
    'cli.selfupdate.rollback_restored' => 'candy-code : le rollback a restauré {old} par-dessus {path} ; la copie conservée est consommée, cette restauration est à usage unique.',
    'cli.selfupdate.sidecar_malformed' => 'candy-code : le sidecar {asset} n\'est pas un sha256 en 64 chiffres hexadécimaux minuscules pour {phar}. Rien n\'a été échangé.',
    'cli.selfupdate.sidecar_names' => 'candy-code : le sidecar nomme {found}, et non {phar}. Rien n\'a été échangé.',
    'cli.selfupdate.sig.deprecated' => 'candy-code : cette version signe les octets bruts du phar avec {asset} ; cette voie héritée charge tout l\'artefact en mémoire et est acceptée pour un cycle de publication supplémentaire. Publiez {replacement} — une signature Ed25519 sur le corps du sidecar sha256 — pour que la vérification ne quitte jamais le flux.',
    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code : {asset} ne vérifie pas le sidecar {sidecar} du {phar} téléchargé contre la clé de publication épinglée. Rien n\'a été échangé.',
    'cli.selfupdate.signature_invalid' => 'candy-code : {asset} ne vérifie pas le {phar} téléchargé contre la clé de publication épinglée. Rien n\'a été échangé.',
    'cli.selfupdate.signature_missing' => 'candy-code : cette version ne porte ni {asset} ni {sig_sidecar}, et la clé de publication épinglée en exige une pour {phar}. Rien n\'a été échangé (--allow-unsigned est la dérogation réservée au dev).',
    'cli.selfupdate.staged_windows' => 'candy-code : la mise à jour est en file d\'attente pour la danse de relance — {new} s\'échange sur {path} à la sortie de ce processus ; la progression est journalisée dans {path}.swap.log et la copie conservée reste à {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code : un self-update précédent a laissé un échange en file d\'attente à {new} qui n\'a jamais été appliqué (son journal d\'échange enregistre les tentatives abandonnées). Cette exécution remplace la file d\'attente avant la mise à jour.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code : l\'assistant d\'échange n\'a pas pu être démarré ; les octets vérifiés restent en file d\'attente à {new} et la copie en cours d\'exécution est intacte. Terminez le renommage vers {path} manuellement, ou relancez self-update une fois que rien ne retient le fichier.',
    'cli.selfupdate.uncomparable' => 'candy-code : cette installation rapporte {current}, qui n\'est pas une version de publication que self-update peut ordonner.',
    'cli.selfupdate.unexpected_operand' => '{operand} : candy-code self-update n\'accepte aucun opérande.',
    'cli.selfupdate.unsigned_allowed' => 'candy-code : --allow-unsigned saute la vérification de signature par clé épinglée ; le sidecar sha256 a toujours lié ces octets. Dérogation dev/test — jamais une habitude de publication.',
    'cli.selfupdate.up_to_date' => 'candy-code : self-update : cette installation est déjà la dernière version ({current}).',
    'cli.selfupdate.usage' => 'Usage : candy-code self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]',
