    'cmd.mcp-auth.disable.done' => '✓ `{server}` désactivé pour cette session — les appels sont refusés dès le prochain tour ; le roster exposé au modèle n\'est pas re-dérivé (règle du cache), ses outils restent donc listés jusqu\'au redémarrage.',
    'cmd.mcp-auth.disable.no-client' => 'Aucun client MCP cette session — rien à désactiver (aucun `.mcp.json` n\'a été approuvé au lancement).',
