    'cmd.mcp-auth.empty' => "Aucun identifiant MCP stocké.\n\nLes identifiants ne concernent que les serveurs exigeant une connexion OAuth ; un\nserveur http déclaré qui n'en a pas besoin fonctionne à partir de son \"url\" seul.\nLes serveurs eux-mêmes sont déclarés sous \"mcpServers\" dans\n<project>/.mcp.json — recette : docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ `{server}` activé pour cette session — les refus de session sont levés dès le prochain tour ; les appels sont de nouveau routés uniquement là où le routage au lancement autorise déjà ce nom.',
