    'cmd.mcp-auth.enable.persist-removed' => '`{server}` retiré de la liste disabledMcpServers de l\'utilisateur ; le lancement ne le refuse plus.',
    'cmd.mcp-auth.enable.unknown' => '! `{server}` n\'est pas un serveur MCP déclaré de cette session — `/mcp list` affiche les noms.',
    'cmd.mcp-auth.enable.usage' => 'Usage : /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Échec de l\'enregistrement : {error}',
    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ Connexion MCP lancée pour `{server}` — en attente du lien du navigateur.\n\nLe processus enfant lie un port loopback ; terminez-le dans un navigateur pendant que le TUI reste réactif. Le client MCP de cette session a mémorisé son store au lancement, le token prend donc effet au PROCHAIN lancement ; `/mcp list` affiche l'identifiant une fois stocké.",
    'cmd.mcp-auth.login-busy' => '! Une connexion pour `{server}` est déjà en cours — terminez ou annulez celle-ci d\'abord (son URL et son statut sont dans le transcript ci-dessus).',
    'cmd.mcp-auth.login-code-delivered' => '✓ Le callback a été livré à la connexion en attente pour `{server}` — le processus enfant termine l\'échange là-bas, et son résultat apparaît dans le transcript.',
    'cmd.mcp-auth.login-code-refused' => '! Impossible de livrer le callback de connexion MCP pour `{server}` : {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "le listener de la connexion en attente n'a pas répondu",
    'cmd.mcp-auth.login-code-reason-host' => 'seuls les hôtes loopback `127.0.0.1` et `localhost` sont acceptés',
    'cmd.mcp-auth.login-code-reason-noslot' => 'aucune connexion pour ce serveur n\'est en attente sur cet hôte',
    'cmd.mcp-auth.login-code-reason-port' => 'le port ne correspond pas au port de callback annoncé par la connexion en attente',
    'cmd.mcp-auth.login-code-reason-scheme' => 'l\'URL de callback doit utiliser le schéma `http` simple que le listener de connexion lie',
    'cmd.mcp-auth.login-code-reason-shape' => 'le format est `/mcp login <server> --code <callback-url>` avec exactement une URL',
    'cmd.mcp-auth.login-done' => '✓ Connexion MCP pour `{server}` terminée (exit {code}). Les tokens s\'attachent au PROCHAIN lancement — démarrez une nouvelle session pour que le grant accompagne les requêtes ; `/mcp list` actualise le panneau.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Connexion MCP pour `{server}` a quitté avec {code} sans stocker de tokens.

Les dernières lignes du processus enfant sont ci-dessus ; le même flux dans un shell (`candy-code mcp auth login {server}`) affiche l'erreur complète et est l'endroit pour déboguer les problèmes d'endpoint ou de port.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Impossible de démarrer le processus enfant de connexion MCP pour `{server}`.\n\nExécutez la forme shell directement : `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "La connexion interactive est une commande shell, pas un tour de chat :\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nIl exécute le flux OAuth authorization-code avec PKCE : votre navigateur\nretourne le code à un listener loopback dans le shell, et les\ntokens stockés sont attachés aux serveurs http correspondants dès le prochain lancement.",
    'cmd.mcp-auth.login-no-entry' => "✗ Impossible de trouver le point d'entrée de ce programme pour forker `mcp auth login {server}`.\n\nExécutez la forme shell directement : `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Connexion MCP lancée pour `{server}` sur l'hôte SERVEUR — son lien arrive ci-dessous ; ouvrez-le dans un navigateur sur votre propre machine. Votre navigateur ne peut pas atteindre directement le listener loopback du serveur : quand il arrive sur une page d'erreur de connexion, copiez l'adresse de cette page et envoyez `/mcp login {server} --code <that-url>` pour transmettre le callback à la connexion en attente. Les tokens s'attachent au PROCHAIN lancement ; `/mcp list` affiche l'identifiant une fois stocké.",
    'cmd.mcp-auth.login-url' => '→ Ouvrez cette URL pour autoriser `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Aucun identifiant trouvé pour `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` enregistré avec succès
ID client : `{client}`
Les requêtes vers un serveur MCP http avec cette URL exacte portent désormais ce jeton automatiquement, rafraîchi avant expiration ; les serveurs démarrés avant cette commande le récupèrent au prochain lancement.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Utilisation : mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` signale désormais qu\'une connexion OAuth est requise.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` est refusé par un motif de refus.',
    'cmd.mcp-auth.reconnect.drifted' => "La configuration MCP a changé depuis le lancement — reconnexion refusée. Une reconnexion redémarre les serveurs exactement tels que `.mcp.json` les contient maintenant, alors que cette session a été admise sur les octets de confiance du lancement ; démarrer des entrées dérivées exécuterait des serveurs que les décisions d'admission n'ont jamais vus. Redémarrez la session pour appliquer le changement ; c'est le seul chemin d'application.",
    'cmd.mcp-auth.reconnect.error' => 'Échec du démarrage : {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Serveurs MCP reconnectés**',
