    'cmd.mcp-auth.reconnect.tool-drift' => 'propose {now} outils ; cette session a été construite avec {was} — la liste exposée au modèle n\'est pas re-dérivée en cours de session, démarrez une nouvelle session pour les adopter',
    'cmd.mcp-auth.reconnect.unknown' => 'Cette session n\'a enregistré aucune empreinte de lancement pour `.mcp.json`, donc une reconnexion ne peut pas prouver que la configuration contient encore les octets du lancement — refusé, le redémarrage est le seul chemin d\'application.',
    'cmd.mcp-auth.removed' => '✓ Identifiants supprimés pour `{server}`',
    'cmd.mcp-auth.status.active' => '● actif',
