    'cmd.mcp-auth.status.expiring' => '● expire bientôt',
    'cmd.mcp-auth.status.none' => '○ aucun identifiant',
    'cmd.mcp-auth.undiscovered' => "! Les points de terminaison OAuth n'ont pas pu être découverts pour `{server}`.\n\nVeuillez les fournir explicitement :\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nRien à découvrir signifie généralement rien à enregistrer : un\nserveur ne nécessitant aucune connexion fonctionne à partir de son \"url\" seul une fois\ndéclaré dans .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Sous-commande inconnue \'{sub}\'. Utilisez : list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Utilisation :\n  mcp auth list                    — lister les serveurs enregistrés\n  mcp auth add <server> [reg-url] [token-url]  — stocker les identifiants OAuth d'un serveur\n  mcp auth remove <server>         — supprimer les identifiants d'un serveur\n  mcp auth login <server>          — afficher la commande shell pour une connexion interactive\n  /mcp reconnect                   — redémarrer les serveurs déclarés, uniquement si .mcp.json correspond encore au lancement\n  /mcp enable <server> [--persist]   — lever le refus de cette session pour un serveur déclaré\n  /mcp disable <server> [--persist]  — refuser les appels d'un serveur déclaré pour cette session",
    'cmd.mcp.description' => 'Gérer l\'authentification des serveurs MCP (list/add/remove ; login affiche la commande CLI) et activer/désactiver par session',
