    'sandbox.hook.not_run' => 'Non exécuté : le hook `{hook}` est enfermé dans le sandbox `{mode}` par sandboxScope, mais le sandbox {name} ne peut pas démarrer sur cet hôte ({reason}). Rien n\'a été exécuté, sandboxé ou non. Indiquez à l\'utilisateur : il peut corriger {name} ({remedy}) ou définir bashSandbox sur "off".',
    'sandbox.lsp.not_started' => 'Non démarré : le serveur de langage `{language}` ({command}) est enfermé dans le sandbox `{mode}` par sandboxScope, mais le sandbox {name} ne peut pas démarrer sur cet hôte ({reason}). Rien n\'a démarré, emprisonné ou non. Indiquez à l\'utilisateur : il peut corriger {name} ({remedy}), définir bashSandbox sur "off", ou exempter ce serveur avec `"sandbox": false` dans sa propre entrée `lsp`.',
    'sandbox.mcp.not_started' => 'Non démarré : le serveur MCP `{server}` est enfermé dans le sandbox `{mode}` par sandboxScope, mais le sandbox {name} ne peut pas démarrer sur cet hôte ({reason}). Rien n\'a démarré, emprisonné ou non. Indiquez à l\'utilisateur : il peut corriger {name} ({remedy}), définir bashSandbox sur "off", ou l\'exempter avec `"sandbox": false` dans son entrée de niveau utilisateur.',
    'sandbox.mcp.opt_out_ignored' => 'Ignoré : l\'opt-out `"sandbox": false` sur le(s) serveur(s) MCP {servers} ne provient pas du fichier de paramètres utilisateur — seul le niveau utilisateur peut exempter un serveur stdio de la prison sandboxScope. Le(s) serveur(s) reste(nt) enfermé(s) comme prévu.',
    'sandbox.runner.skipped' => 'Ignoré : l\'exécution {scope} est enfermée dans le sandbox `{mode}` par sandboxScope, mais le sandbox {name} ne peut pas démarrer sur cet hôte ({reason}). Rien n\'a été exécuté, sandboxé ou non. Indiquez à l\'utilisateur : il peut corriger {name} ({remedy}) ou définir bashSandbox sur "off".',
