    'chat.command.error' => '**Error:** {error}',
    'chat.compact.idle_advisory' => 'Cette session est inactive depuis plus d\'une heure et a atteint ~{tokens} tokens estimés, dépassant sa fenêtre de contexte de {limit} tokens. Exécutez /compact pour réduire le contexte avant de continuer. Envoyer un autre message ne l\'enverra pas tel quel : le prochain tour dépasse le seuil de compaction automatique, les échanges anciens sont donc résumés d\'abord, et le tour est refusé si cela ne libère pas assez d\'espace.',
    'chat.compact.idle_auto_scheduled' => 'Compaction automatique en inactivité : la session a dépassé la fenêtre d\'inactivité avec un transcript au-delà du seuil de compaction (~{tokens} tokens estimés pour une fenêtre de {limit} tokens), la demande de résumé a donc été envoyée sans intervention. Le pliage s\'applique au prochain tour ; rien n\'est facturé deux fois et aucune réponse n\'est envoyée.',
    'chat.compact.idle_folded' => 'Compaction pendant l\'inactivité : ~{before} tokens estimés sont passés à ~{after}. `compaction.idleAuto` a exécuté le seuil automatique pendant que la session restait inactive, les échanges condensés sont désormais des résumés.',
