    'chat.turn.loop_guard' => 'Ce tour a été terminé par le garde anti-boucle d\'appels répétés : le modèle a appelé {tool} {count} fois avec les mêmes arguments et a obtenu le même résultat à chaque fois. La réponse ci-dessus décrit où il s\'est arrêté. Orientez-le vers une approche différente, ou dites `continue` une fois que quelque chose a changé.',
    'chat.turn.output_limit' => 'Le fournisseur a arrêté cette réponse à sa limite de sortie, le texte ci-dessus peut donc s\'interrompre en cours de pensée. Augmentez `maxOutputTokens` dans ~/.candy-code/config.json pour une réponse unique plus longue, ou demandez le reste dans votre prochain message.',
    'chat.turn.steps_exhausted' => 'Ce tour a utilisé tous ses pas d\'outils avant que le travail soit terminé, la réponse ci-dessus décrit donc où il s\'est arrêté — ce qui est fini et ce qui reste — et non une réponse complète. Dites `continue` pour reprendre de là, ou augmentez le plafond pour des tours agentiques plus longs — un flag --max-turns au lancement prime sur le paramètre `maxToolSteps` dans ~/.candy-code/config.json, augmentez donc celui qui est en vigueur.',
    'chat.turn.unpriced_model' => 'Cette application n\'a pas de prix enregistré pour le modèle `{model}`, ce tour a donc été facturé $0.00 comme borne inférieure, et non comme un appel gratuit — les totaux de dépenses et le plafond de dépenses sont sous-évalués tant qu\'un tarif n\'existe pas. Déclarez-en un sous `modelPrices` dans ~/.candy-code/config.json (USD par 1M tokens, clés `input` et `output`) pour le tarifer.',
    'chat.verbose.failed' => 'Bascule verbose refusée : {error}',
    'chat.verbose.off' => 'Sortie verbose des outils désactivée — les lignes se replient à nouveau · cette session uniquement, rien n\'est écrit',
    'chat.verbose.on' => 'Sortie verbose des outils activée — les lignes restent dépliées · cette session uniquement, rien n\'est écrit',
    'chat.verbose.unsavable' => 'Rien ici ne sauvegarde les paramètres, la bascule verbose ne peut donc pas changer',
    'chat.voice.busy' => 'Une autre prise vocale est encore en cours de transcription — celle-ci a été abandonnée, rien n\'a été conservé',
    'chat.voice.recording' => '● rec · Alt+V stop · Esc annuler',
    'chat.voice.transcribing' => 'transcription…',
    'chat.workflow.cancelled' => '_Workflow annulé : arrêt de ses agents. Son rapport suit._',
    'host.agents.accept.bad_name' => '`{name}` n\'est pas un nom de brouillon. Un brouillon est un fichier directement sous le répertoire des brouillons, et vous passez son nom — lettres minuscules, chiffres, points, underscores et tirets — à /agents accept.',
    'host.agents.accept.exists' => 'Un preset nommé {name} existe déjà sous {dir}/, et /agents accept n\'écrase jamais un preset actif. Supprimez ou renommez ce preset d\'abord, ou créez un brouillon sous un autre nom avec /agents new.',
    'host.agents.accept.frontmatter' => 'Le brouillon {name} n\'a pas de bloc frontmatter qui se parse en mapping, il n\'a donc pas été promu. Exécutez /agents new à nouveau, ou corrigez le fichier et acceptez-le une nouvelle fois.',
    'host.agents.accept.missing' => 'Aucun brouillon nommé {name} sous {dir}/. Exécutez /agents new pour en créer un, ou /agents proposed pour lister les brouillons.',
    'host.agents.accept.mode' => 'Le brouillon {name} déclare `permissionMode: {mode}`, qui ne fait pas partie des modes de ce port. Déclarez-en un parmi : {modes} — ou omettez la clé pour `default`.',
    'host.agents.accept.moved' => 'Le brouillon {name} est maintenant {path} — le roster de la prochaine session le charge comme preset de projet.',
    'host.agents.accept.policy' => 'Politique déclarée par ce brouillon (affichée verbatim avant le déplacement) :',
    'host.agents.accept.policy_line' => '  - {key} : {value}',
    'host.agents.accept.self_grant' => '**Heads-up:** `{mode}` est une auto-gratification — le preset promu démarre les exécutions avec une surface de permission d\'autant plus large qu\'une session ordinaire. Le promouvoir ici vaut votre consentement ; le brouillon lui-même ne pouvait pas l\'accorder.',
    'host.agents.accept.type' => 'Le brouillon {name} déclare `{key}` comme une valeur que le lecteur de preset ne peut pas typer — il attend une chaîne ou une liste de chaînes.',
    'host.agents.accept.unknown' => 'Le brouillon {name} déclare `{key}`, une clé sur laquelle aucun lecteur de preset n\'agit{hint}. Supprimez-la ou corrigez l\'orthographe ; /agents accept ne promeut que les fichiers dont les clés sont lues par ce port.',
    'host.agents.error' => 'La commande /agents draft a échoué : {error}',
    'host.agents.new.dispatched' => 'Demande à l\'agent de rédiger un preset à partir de cette conversation ; il écrit uniquement le niveau brouillon, et rien n\'est promu tant que vous n\'exécutez pas /agents accept.',
    'host.agents.proposed.heading' => 'Brouillons d\'agents proposés :',
    'host.agents.proposed.none' => 'Aucun brouillon en attente sous {dir}/. Exécutez /agents new pour que l\'agent en rédige un à partir de cette conversation.',
    'host.agents.usage' => 'Usage : /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Gestionnaire d\'agents non configuré — aucun runtime de sous-agent n\'est attaché à ce lancement, /agents ne peut donc pas démarrer ni surveiller d\'agents. Un lancement `candy-code` standard en a toujours un ; une build d\'intégration hôte doit l\'attacher.',
    // C-AGT-4.b: the `use` verb. Soft-appended after the block's last row;
    // rows answer `/agent use <preset|default>` and the Alt+A cycle.
    'host.agents.use_default' => 'Retour au défaut de session ordinaire — rien de ce qu\'un /agent use précédent avait restreint ne reste appliqué.',
    'host.agents.use_switched' => '{name} est désormais l\'agent principal de cette session — ses outils, modèle et plancher de permission restent en vigueur jusqu\'à ce que vous reveniez ; un redémarrage exécute le défaut de session ordinaire.',
    'host.agents.use_turn_running' => 'Un tour est en cours — l\'agent principal bascule entre les tours, comme un changement de mode de permission.',
    'host.agents.use_unavailable' => 'Cette session exécute un backend echo ordinaire ; il n\'y a pas de roster d\'outils ni de porte pour qu\'un agent principal restreigne.',
    'host.agents.use_unknown' => 'Aucun preset de roster nommé {name}. Exécutez /agents pour lister le roster.',
    'host.bg.active' => 'Sessions en arrière-plan actives : {sessions}',
    'host.bg.backgrounded' => 'Placé en arrière-plan sous {id} (« {name} ») — utilisez /agents pour vérifier le statut, /bg stop {id} pour annuler.',
    'host.bg.default_name' => 'Tâche en arrière-plan',
    'host.bg.forked' => 'Forké en session en arrière-plan {id} (\'{name}\') — utilisez /agents pour vérifier l\'état, /bg stop {id} pour annuler.',
    'host.bg.none_active' => 'Aucune session en arrière-plan active.',
    'host.bg.not_configured' => 'Sessions en arrière-plan non configurées — ce lancement ne peut pas exécuter de tâches hors du premier plan. Un lancement `candy-code` standard dispose toujours du superviseur ; une build d\'intégration hôte doit en attacher un avant que /bg et /fork fonctionnent.',
    'host.bg.start_failed' => 'Impossible de démarrer la session en arrière-plan \'{name}\' : {error}',
