    'host.bg.stop.stopped' => 'Session en arrière-plan {session} arrêtée.',
    'host.bg.stop.unknown' => 'Aucune session en arrière-plan {id} dans cette exécution — /bg stop liste les actives.',
    'host.bg.stop.unreachable' => 'Impossible d\'arrêter la session en arrière-plan {session} — son démon est injoignable ou n\'a pas pu être signalé en sécurité.',
    'host.bg.stop_usage' => 'Utilisation : /bg stop <session-id>',
    'host.bg.usage' => 'Utilisation : /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}` n\'a pas été exécuté : /{name} provient d\'un bundle de plugin, un paquet empaqueté par quelqu\'un d\'autre. Une ligne de bundle refuse les formes shell quel que soit le niveau d\'installation — aucune autorisation locale ne la débloque, et un opt-in par origine est le suivi prévu — le reste de la commande a été envoyé.]',
    'host.command_shell.mcp_refused' => '[!`{command}` n\'a pas été exécuté : /{name} est un prompt MCP récupéré depuis un serveur, du texte arrivé par le réseau. Un corps récupéré refuse les formes shell quel que soit ce que ce projet approuve — aucune autorisation locale ne le débloque, et un opt-in par origine est le suivi prévu — le reste du prompt a été envoyé.]',
    'host.loop.not_configured' => 'Planifications non configurées pour cette session — /loop n\'a pas d\'horloge sur laquelle tourner. Un lancement `candy-code` standard en porte toujours une ; une build d\'intégration hôte doit la fournir.',
    'host.loop.usage' => 'Utilisation : /loop <interval> <prompt> — intervalle du type 90s, 15m, 2h, 1d (plancher 10s). La boucle vit dans ce processus ; /schedules la liste, /schedules delete la termine.',
    'host.loop.bad_interval' => 'Intervalle invalide : {interval}. Utilisez des secondes (60) ou un suffixe : 90s, 15m, 2h, 1d.',
    'host.loop.registered' => 'Boucle {name} : toutes les {every} — `{prompt}` est mis en file comme un tour ici (premier déclenchement dans un intervalle). Se termine avec le processus, ou /schedules delete {name}.',
    'host.loop.queued' => "La boucle '{name}' est due : son prompt est mis en file pour cette session.",
    'host.output_style.arity' => '/output-style accepte un nom de style ou `off` ; lu comme `{args}`.',
    'host.output_style.available' => 'Styles disponibles : {names}',
    'host.output_style.cleared' => 'Aucun style de sortie actif — le prompt s\'exécute sans règlebook de style à partir du prochain tour.',
    'host.output_style.column_source' => 'Source',
    'host.output_style.column_state' => 'État',
    'host.output_style.column_style' => 'Style',
    'host.output_style.empty' => "Aucun style de sortie trouvé.\nUn style est un fichier markdown dans ~/.candy-code/styles/ (ou .candy-code/styles/ dans le projet),\nnommé par son nom de fichier : terse.md se sélectionne avec /output-style terse.",
    'host.output_style.footer' => "/output-style <name> sélectionne un style ; un seul est actif à la fois, et un\nchangement efface le précédent. /output-style off vide l'emplacement. `off` est un\nmot réservé — un fichier nommé off.md ne peut pas être sélectionné. Un style désactivé par son\npropre frontmatter (`enabled: false`) reste hors du prompt quel que soit son nom.",
    'host.output_style.heading' => 'Styles de sortie (session uniquement — rien n\'est écrit dans la config) :',
