    'host.output_style.self_disabled' => "\nSon propre frontmatter indique enabled: false, il reste donc hors du prompt tant que cette ligne ne change pas — la sélection ne peut pas outrepasser un fichier qui s'est désactivé lui-même.",
    'host.output_style.set' => "Style {name} : ACTIF pour cette session.{note}\nIl s'applique au prompt à partir du prochain tour ; un style précédent est retiré — un seul est actif.",
    'host.output_style.state_active' => 'actif',
