    'host.doctor.column_detail' => 'Détail',
    'host.schedules.not_configured' => 'Planifications non configurées pour cette session.',
    'host.schedules.usage' => 'Utilisation : /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. Les lignes vivent dans ~/.candy-code/schedules.json ; /schedules add en crée une via les bornes de la fabrique de l\'outil Schedule, /loop en enregistre une éphémère.',
    'host.schedules.none' => 'Aucune planification. /schedules add <name> <interval> <prompt> en crée une via les mêmes bornes que l\'outil Schedule, ou écrivez une ligne dans ~/.candy-code/schedules.json (`name`, `every` en secondes, `prompt`, `root` — le répertoire du projet où elle se déclenche ; optionnel `provider`, `permissionMode` (les orthographes de classe bypass sont refusées ; laissez-le absent pour le plancher non interactif), `enabled`, `timeoutSeconds`, `kind` (`task` répond, `heartbeat` peut rester silencieux)), ou /loop une pour cette session. docs/SCHEDULES.md décrit le format.',
    'host.schedules.row' => '{state}{kind}{name} — toutes les {every}, prochaine {next} @ {root} : {prompt}',
