    'host.compact.self_client_only' => '`/compact --self` demande à l\'agent d\'écrire son propre résumé — c\'est la voie interactive TUI. Exécutez `/compact` pour replier les résumés écrits par le modèle déjà conservés pour cette session.',
    'host.compact.spend_cap' => 'Plafond de dépenses atteint ({spent} sur ${cap}), le modèle n\'a donc pas été invité à résumer — compacté avec l\'heuristique locale à la place. ',
