    'host.compact.summarising.other' => 'Résumé de {count} échanges antérieurs avec le modèle — la transcription se compactera à leur arrivée.',
    'host.compact.thrash' => 'La compaction de contexte a été exécutée {times} fois de suite et la transcription est repassée au-dessus de la limite à chaque fois, donc ce prompt n\'a pas été envoyé et aucune autre compaction n\'a été tentée. Les échanges récents que la réécriture conserve intégralement sont ce qui ne rentrera pas — réduisez les plus volumineux (la sortie des outils est généralement le gros du volume), ou recommencez avec /rewind ou /clear. /model avec une fenêtre de contexte plus grande résout aussi ce problème.',
    'host.compact.tier_report' => 'Le contexte a atteint le palier de compaction automatique, les échanges anciens ont donc été résumés : {before} messages -> {after} messages, ~{saved} % du nombre estimé de jetons libéré (~{tokens} jetons estimés maintenant, pour une fenêtre de contexte de {limit} jetons).',
    'host.compact.truncated.one' => '{count} message a atteint {tier} à lui seul, il a donc été tronqué pour tenir dans la fenêtre de contexte plutôt que de refuser le tour : ~{tokens} jetons estimés maintenant, pour une fenêtre de contexte de {limit} jetons. Le texte envoyé au modèle porte un marqueur à l\'endroit de la coupe ; votre original complet reste dans la transcription, caché au modèle.',
    'host.compact.truncated.other' => '{count} messages ont atteint {tier} à eux seuls, ils ont donc été tronqués pour tenir dans la fenêtre de contexte plutôt que de refuser le tour : ~{tokens} jetons estimés maintenant, pour une fenêtre de contexte de {limit} jetons. Le texte envoyé au modèle porte un marqueur à l\'endroit de chaque coupe ; vos originaux complets restent dans la transcription, cachés au modèle.',
