    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` ressemble à une commande slash, pas à un filtre — Entrée ici reprendrait la meilleure correspondance. Appuyez sur Escape et tapez la commande dans la saisie à la place.',
    'tui.app.stop_all_armed' => 'Sur le point d\'arrêter tous les agents en cours — appuyez à nouveau sur "s" dans les 3 s pour confirmer.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'manquant — le calcul de largeur d\'image (mb_*) ne peut pas s\'exécuter ; réinstallez PHP avec ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'manquant — le calcul de largeur graphème/IntlChar ne peut pas s\'exécuter ; réinstallez PHP avec ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json ou hooks.yaml a été modifié depuis le dernier lancement. Les nouveaux hooks du projet restent en quarantaine pour ce lancement uniquement — vérifiez ~/.candy-code/config.json et hooks.yaml, puis ils seront appliqués',
    'appLaunch.notice.project_policy_changed' => '⚠ Le hooks.yaml d\'un projet de confiance contient des entrées que le dernier lancement n\'a jamais vues. Les nouveaux hooks du projet restent en quarantaine pour ce lancement uniquement — vérifiez le .candy-code/hooks.yaml de ce dépôt, puis ils seront appliqués',
    'appLaunch.notice.bypass_mode' => '⚠ Le mode de permission est bypass-permissions : chaque appel d\'outil s\'exécute sans invite. Modifiez-le avec /permissions (TUI), --permission-mode, ou définissez un autre mode de permission dans ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p démarre en mode de permission default : une exécution non supervisée refuse tout appel d\'outil qui demanderait une confirmation. Passez --permission-mode (bypass-permissions exécute tout) pour les exécutions scriptées',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview est activé par défaut pour ce lancement : les appels en mode auto signalés sont revus par le modèle de titre, et chaque revue est un appel payant au modèle. Définissez autoReview sur false dans ~/.candy-code/config.json pour désactiver',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} a restreint les permissions de ce lancement : {count} règle(s) deny/ask chargée(s) en premier, {dropped} règle(s) allow supprimée(s) — un fichier de projet ne peut pas accorder allow',
    'appLaunch.notice.restricted' => '⚠ --restricted : ce lancement s\'exécute sans outils d\'exécution de code — Bash, PtyRun, Task, Workflow, ShellStop et mcp_call sont absents de chaque ensemble exposé au modèle ; les outils de fichiers restent sous leur confinement de chemin et /permissions ne peut pas rétablir les outils supprimés',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode : les racines de projets de confiance, les bundles, et les skills, commandes et agents externes sont tous ignorés pour ce lancement — il se comporte comme si rien n\'avait jamais été marqué comme de confiance',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Aucun fournisseur n\'est configuré, donc cette session fonctionne sur le backend echo hors-ligne intégré — les réponses sont renvoyées localement, aucun modèle n\'est appelé. Exécutez `candy-code doctor` pour voir ce qu\'un fournisseur requiert, puis appuyez sur Ctrl+P pour changer de modèle une fois qu\'un est configuré.',
    'keys.chat.repaint' => 'Effacer l\'écran et redessiner le cadre',
    'keys.unbound' => 'non lié',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ Le hook Claude Code `async` `{hook}` s\'est terminé avec {code}. Un hook `async` demande de surveiller un appel d\'outil plutôt que de le bloquer, il n\'a donc aucun pouvoir pour en bloquer un et l\'appel a procédé. Ce qu\'il a dit : {reason}',
    'hooks.notice.claude_dialect' => '⚠ Le hook Claude Code `{hook}` s\'est terminé avec {code}, ce que Claude Code interprète comme une plainte non bloquante plutôt qu\'une décision, donc l\'appel d\'outil a procédé. Ce qu\'il a dit : {reason}',
    'hooks.notice.said_nothing' => '(rien sur stderr)',
    'hooks.notice.system_message' => '⚠ Le hook `{hook}` vous a laissé un message : {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'Le hook HTTP `{hook}` est configuré avec une URL qui ne peut pas être utilisée ({reason}) ; la cible affichée est {target}. Un hook qui ne peut pas indiquer où il va n\'a pas approuvé cet appel.',
    'hooks.http.deny_scheme' => 'Le hook HTTP `{hook}` nomme {target}, qui n\'est pas une URL http ou https. candy-code ne compose les hooks que via ces deux schémas, et l\'appel est refusé plutôt qu\'exécuté sur un transport non vérifié.',
    'hooks.http.deny_credentials' => 'Le hook HTTP `{hook}` contient des identifiants dans son URL ({target}). Un mot de passe écrit dans une URL se retrouve dans les logs et les proxys, il est donc refusé ici ; envoyez-le comme un en-tête dont la valeur lit un nom `allowedEnvVars`.',
    'hooks.http.deny_blocked_target' => 'Le hook HTTP `{hook}` ne peut pas être consulté : {reason} ({target}). Les adresses privées et link-local sont refusées par la même règle qu\'une récupération sortante, et une protection qui n\'a jamais été atteinte n\'a pas approuvé cet appel.',
    'hooks.http.deny_unanswered' => 'Le hook HTTP `{hook}` n\'a pas répondu ({reason}) ; la cible était {target}. Un hook qui n\'a pas pu être atteint n\'a pas approuvé cet appel, il est donc refusé.',
    'hooks.http.deny_header_injection' => 'Le hook HTTP `{hook}` ne peut pas envoyer son en-tête `{field}` : le nom ou sa valeur contient un caractère de contrôle, ce qui relève du cadrage de requête et non d\'une valeur d\'en-tête. Rien n\'a été envoyé à {target} et l\'appel est refusé.',
    'hooks.http.notice_unanswered' => '⚠ Le hook HTTP `{hook}` n\'a pas répondu ({reason}), il n\'a donc pas pu bloquer l\'appel. Il a été interrogé sur {target}.',
    'hooks.http.reason_unreachable' => 'la connexion ou la requête a expiré dans son propre délai d\'attente de hook',
    'hooks.http.reason_oversized' => 'la réponse était plus grande que {bytes} octets et s\'est terminée nulle part',
    'hooks.http.reason_no_status' => 'la réponse ne contenait aucune ligne de statut HTTP',
    'hooks.http.reason_redirect' => 'elle a redirigé, et un appel de hook ne suit aucune redirection',
    'hooks.http.reason_status' => 'la réponse n\'était pas un statut 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'Le hook de prompt `{hook}` n\'a pas répondu ({reason}). Un hook dont le verdict n\'a jamais été retourné n\'a pas approuvé cet appel, il est donc refusé.',
    'hooks.prompt.notice_unanswered' => '⚠ Le hook de prompt `{hook}` n\'a pas répondu ({reason}), il n\'a donc pas pu bloquer l\'appel.',
    'hooks.prompt.reason_call_failed' => 'le modèle n\'a pas pu être interrogé',
    'hooks.prompt.reason_empty_verdict' => 'Le hook de prompt `{hook}` a refusé cet appel sans donner de raison.',
    'hooks.prompt.reason_no_backend' => 'ce lancement n\'a pas de backend de titre pour l\'interroger',
    'hooks.prompt.reason_no_prompt' => 'l\'entrée contient un prompt vide à interroger',
    'hooks.prompt.reason_unparseable' => 'sa réponse n\'était pas le seul objet JSON avec un booléen `ok` qu\'il est tenu de retourner',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modèle que l\'outil `Advisor` consulte pour un second avis ; non défini — le défaut — n\'offre pas l\'outil du tout (il n\'y a pas de repli sur un modèle bon marché : l\'intérêt est un modèle que vous avez choisi).',
    'settings.allowedTools.help' => 'Liste blanche de noms d\'outils ou de globs ; non défini offre tous les outils.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"} : le trailer et la ligne de PR que les directives git demandent.',
    'settings.autoCommit.help' => 'off, turn (un commit par tour, message du modèle de titre) ou edit (un par Write/Edit) ; /undo le révoque.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'Sous auto, un appel signalé par le classificateur de sécurité (autre qu\'une découverte de sécurité, qui demande toujours) est revu par le modèle de titre, qui l\'autorise, vous demande ou le refuse. Activé par défaut dès qu\'un modèle de revue existe, et un lancement qui engage ce défaut le signale une fois ; définissez false pour désactiver. Chaque revue est un appel payant au modèle.',
    'settings.autoReviewModel.help' => 'Le `provider/model` sur lequel le relecteur auto fonctionne, par exemple `openai/gpt-4.1-mini` ; vide signifie le modèle de titre. Un fournisseur qui ne peut pas être construit laisse le relecteur désactivé avec un avertissement de lancement.',
    'settings.autoReviewScope.help' => 'Ce que `autoReview` envoie au relecteur : `shell` (le défaut) est chaque commande shell non en lecture seule que la liste de motifs a passée ; `writes` examine aussi `Edit`, `Write`, `ApplyPatch` et `WebFetch`, avec le diff en attente pour les outils d\'écriture ; `all` examine chaque appel que la liste a passée. Toute autre orthographe se comporte comme `shell`. Chaque revue est un appel payant au modèle.',
    'settings.autoTest.help' => 'Après un tour qui a modifié un fichier, exécutez `testCommand` ; en cas d\'échec la sortie est renvoyée au modèle, au plus 3 fois par tour.',
    'settings.bashInteractiveIdleSeconds.help' => 'Secondes pendant lesquelles une exécution Bash `interactive: true` peut ne rien afficher avant d\'être arrêtée comme attendant une touche.',
    'settings.bashMaxTimeoutSeconds.help' => 'Le plus grand `timeout` qu\'une commande Bash peut demander ; les valeurs supérieures sont bornées à celui-ci.',
    'settings.bashSandbox.help' => 'Linux exécute Bash dans bubblewrap ; macOS l\'exécute dans un profil Seatbelt via `sandbox-exec` — inscriptible uniquement dans la racine de travail (`no-network` coupe aussi le réseau). `allowlist` (Linux) route le trafic réseau sortant via le proxy sortant du lancement, qui n\'accorde que les hôtes listés dans `sandboxAllowedDomains` : avec la liste vide par défaut il se comporte EXACTEMENT comme `no-network` tant que vous ne listez pas d\'hôtes, et même une fois listés, le trafic non-HTTP (ssh, ports de base de données) et tout hôte non listé échouent. Sur macOS `allowlist` est appliqué comme `no-network`. Refuse les commandes quand la prison ne peut pas démarrer ; une valeur non reconnue signifie `no-network`, jamais `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Définissez `true` pour permettre à une commande `Bash` en sandbox de créer son propre espace de noms utilisateur, ce dont podman ou buildah sans root et un sandbox Chromium ont besoin. Le défaut `false` exécute bubblewrap avec `--unshare-user --disable-userns`, bloquant la voie habituelle de sortie d\'une prison de montage ; sur un hôte dont bubblewrap est trop ancien pour ces drapeaux, la prison exécute l\'ensemble simple et sa propre description le signale.',
    'settings.bashTimeoutSeconds.help' => 'Secondes pendant lesquelles une commande Bash peut s\'exécuter quand le modèle ne passe pas de `timeout` ; jamais au-dessus du plafond Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Budget horloge murale d\'un lot d\'appels d\'outils que le chemin natif chat (`command` provider) fourche ; les traînards sont tués.',
    'settings.claudeMcpArgs.help' => 'Arguments pour ce binaire ; non défini utilise le défaut du transport.',
    'settings.claudeMcpBinary.help' => 'Chemin absolu du binaire `claude` que le transport claude-mcp peut lancer.',
    'settings.claudeMcpEnv.help' => 'Variables d\'environnement littérales transmises à ce binaire.',
    'settings.compaction.autoPercent.help' => 'Part de fenêtre à laquelle les échanges plus anciens sont condensés automatiquement avant que le prompt soit envoyé.',
    'settings.compaction.autoTokens.help' => 'Plafond absolu sur le palier automatique et le budget d\'étapes en cours de tour. 0 désactive le plafond.',
    'settings.compaction.blockPercent.help' => 'Part de fenêtre au-delà de laquelle un prompt est refusé tant que de l\'espace n\'est pas libéré ; le seul palier qui refuse.',
    'settings.compaction.blockTokens.help' => 'Plafond absolu sur le palier bloquant ; non défini par défaut. Le définir permet à un plafond de refuser des prompts.',
    'settings.compaction.idleAuto.help' => 'Compacter une session inactive au-dessus du palier pendant l\'inactivité au lieu d\'attendre le prochain prompt, en utilisant la mécanique du palier automatique (plafond de dépense et coupeur de thrash s\'appliquent). off : jamais ; hour : après la fenêtre complète compaction.idleOfferSeconds ; cacheTtl : juste avant l\'expiration du cache de prompt du fournisseur — une heure quand le fournisseur marque les points de rupture de cache, environ 5 min pour les caches côté serveur, jamais quand il ne signale rien de mis en cache — une fois que l\'historique dépasse un plancher sous le palier automatique, car le prochain prompt préremplirait sinon toute la conversation sans cache ; sur le tick de 60 secondes un cache de 5 min se replie à environ 4 minutes d\'inactivité. Coûte un appel fournisseur en arrière-plan ; nécessite compaction.idleOfferSeconds supérieur à 0. Un booléen continue d\'être lu : true signifie hour, false signifie off.',
    'settings.compaction.idleOfferSeconds.help' => 'Une session ayant dépassé toute sa fenêtre de contexte qui est restée intacte aussi longtemps se voit proposer /compact au lieu d\'envoyer le prompt. 0 ne propose jamais.',
    'settings.compaction.keepRecent.help' => 'Échanges utilisateur/assistant les plus récents qu\'une compaction conserve intégralement.',
    'settings.compaction.mode.help' => 'llm : le modèle de résumé écrit les résumés (l\'heuristique est son repli) ; heuristic : résumés locaux d\'une ligne, jamais d\'appel au modèle ; off : rien ne se compacte seul, /compact fonctionne toujours et le palier bloquant refuse toujours.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" ou "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} surchargeant les trois plafonds ; 0 efface un.',
    'settings.compaction.refillLimit.help' => 'Compactions automatiques consécutives qui peuvent repasser au-dessus de leur palier, prompt non envoyé, avant que le prochain prompt soit refusé au lieu d\'être à nouveau compacté.',
    'settings.compaction.reminderPercent.help' => 'Part de fenêtre à laquelle le rappel « envisager de compacter » et le résumé en arrière-plan anticipé démarrent ; sous le palier automatique.',
    'settings.compaction.reminderTokens.help' => 'Plafond absolu sur le palier de rappel : il se déclenche à min(pourcentage, celui-ci). 0 désactive le plafond.',
    'settings.compaction.summaryAssistantChars.help' => 'Les réponses de l\'assistant plus longues que ceci deviennent « [échanges d\'information] » dans une ligne de résumé heuristique.',
    'settings.compaction.summaryUserChars.help' => 'Caractères d\'un message utilisateur que la ligne de résumé heuristique conserve.',
    'settings.compaction.toolOutputChars.help' => 'Caractères de la moitié assistant d\'un échange condensé que le modèle de résumé reçoit.',
    'settings.connectTimeoutSeconds.help' => 'Délai de liaison à un hôte fournisseur (DNS, TCP, TLS) ; pas un délai de requête.',
    'settings.contextPruning.compress.help' => 'manual offre Compress uniquement sur un tour que vous démarrez avec /compress, un appel ; auto l\'offre sur chaque tour où le modèle peut élaguer.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Résultats d\'outils depuis le dernier prompt après lesquels une longue boucle d\'outils est rappelée pour élaguer.',
    'settings.contextPruning.maxContextTokens.help' => 'Taille de contexte au-dessus de laquelle la ligne la plus récente porte le rappel plus fort « élaguer maintenant ».',
    'settings.contextPruning.minContextTokens.help' => 'Taille de contexte en dessous de laquelle le modèle n\'est jamais rappelé pour élaguer ; ne doit pas dépasser la taille du rappel dur.',
    'settings.contextPruning.mode.help' => 'auto élaguent les lignes obsolètes à chaque début de tour ; manual uniquement sur /sweep ; off n\'affiche pas de balises ref. /pruning le surcharge par session.',
    'settings.contextPruning.nudgeFrequency.help' => 'Lignes nouvelles qu\'un rappel attend après le dernier, pour ne pas se répéter à chaque étape.',
    'settings.contextWindow.help' => 'Surcharge de fenêtre de tokens : un nombre pour le modèle du fournisseur, ou {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Afficher chaque répertoire ou fichier de commande personnalisée refusé sur stderr, pas seulement le compteur d\'une ligne du lancement.',
    'settings.debug.rules.help' => 'Afficher chaque répertoire ou fichier de règles refusé sur stderr.',
    'settings.debug.skills.help' => 'Afficher chaque fichier de skill ignoré et chaque répertoire de skills refusé sur stderr, pas seulement le compteur d\'une ligne du lancement.',
    'settings.debug.stream.help' => 'Afficher la ligne « l\'observateur onToken a levé, détachement » sur stderr quand le flux d\'un embedder échoue en cours de tour.',
    'settings.diffPreviewRows.help' => 'Lignes d\'un diff Edit ou Write affichées dans le transcript avant que le reste soit résumé.',
    'settings.diffStyle.help' => 'Disposition du diff dans le transcript : `auto` peint les hunks côte à côte sur les terminaux larges (120 colonnes ou plus) et unifiés ailleurs, `unified` toujours une colonne, `split` toujours deux. Les corps de diff sont teintés par token dans les deux dispositions ; la colonne de marqueur `+`/`-` garde sa couleur.',
    'settings.disabledMcpServers.help' => 'Noms de serveurs `.mcp.json` ou globs (`untrusted_*`) qui ne sont jamais démarrés, listés ni appelés, pour l\'agent principal et chaque sous-agent.',
    'settings.disabledRules.help' => 'Packs de règles de niveau utilisateur tenus hors du prompt dès le premier tour.',
    'settings.disabledSkills.help' => 'Skills retirés de la découverte ; l\'emporte aussi sur enabledSkills.',
    'settings.disabledTools.help' => 'Noms d\'outils ou globs retirés de l\'ensemble d\'outils exposé au modèle.',
    'settings.doubleEscSeconds.help' => 'Vitesse à laquelle le second Esc doit suivre le premier pour annuler un tour en cours.',
    'settings.embeddingModel.help' => 'Modèle d\'embedding pour le rappel de mémoire par tour ; non défini classe les notes par mot-clé uniquement.',
    'settings.enabledSkills.help' => 'Skills dont les corps complets accompagnent le prompt système à chaque tour.',
    'settings.env.diffMaxBytes.help' => 'Octets que chacune des deux sections de diff git conserve avant d\'être tronquée avec une note.',
    'settings.env.gitDiffAfterWrites.help' => 'Après une étape qui a écrit des fichiers, afficher les diffs git stagés et non stagés dans le contexte du tour.',
    'settings.expandToolOutput.help' => 'Afficher en entier la sortie de chaque appel d\'outil terminé dans la transcription ; Ctrl+O ou un clic replie toujours un élément.',
    'settings.extraBody.help' => 'Champs de requête de premier niveau ajoutés à chaque requête du fournisseur `custom`.',
    'settings.formatCommands.help' => 'Commande de formatage post-édition par extension de fichier ({"php": "vendor/bin/php-cs-fixer fix {file}"}) ; exécutée avant le lint post-édition, réécrit le fichier. Désactivé par défaut.',
    'settings.formatAuto.help' => 'Laisser la table d\'extensions intégrée (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, le prettier du node_modules du projet) formater un fichier édité quand `formatCommands` ne nomme aucune commande pour son extension. Les entrées explicites l\'emportent ; un projet a toujours besoin de `trustedProjectHooks`. Désactivé par défaut.',
    'settings.globMaxMatches.help' => 'Chemins qu\'un Glob collecte avant que son parcours ne s\'arrête ; le plafond de sortie borne toujours le résultat.',
    'settings.grepTimeoutSeconds.help' => 'Secondes qu\'une recherche Grep peut exécuter avant d\'être tuée ; les résultats trouvés jusqu\'à l\'échéance reviennent en résultat partiel.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Secondes qu\'une entrée de hook sans `timeout:` peut s\'exécuter avant d\'être tuée et comptée comme un refus.',
    'settings.includeGitInstructions.help' => 'Si les directives génériques de commit de l\'outil Bash accompagnent le prompt système.',
    'settings.instructions.help' => 'Globs de fichiers dont le contenu devient du texte autoritaire du prompt système.',
    'settings.instructions.walkToRoot.help' => 'Opt-in : lire aussi les fichiers d\'instruction au-dessus du marqueur .git le plus proche, jusqu\'au répertoire personnel inclus. Niveau utilisateur uniquement ; chaque lecture conserve son périmètre et son budget de taille.',
    'settings.instructionsExclude.help' => 'Globs de fichiers d\'instruction à ignorer, enregistrés comme refus ; niveau utilisateur uniquement — un dépôt ne peut pas museler son opérateur. Les fichiers dans le checkout correspondent par chemin relatif au checkout ; les fichiers ancêtre et forcés hors de celui-ci correspondent par chemin absolu, donc `**/CLAUDE.local.md` atteint aussi les copies ancêtre.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"} : lier une touche SUPPLÉMENTAIRE à un identifiant de raccourci (la référence /keys les nomme) — Ctrl+<key>, Alt+<key>, Shift+<key>, ou une touche de fonction seule ; le raccourci livré continue de fonctionner. Présente mais inutilisable refuse le lancement ; retirer la touche pour les raccourcis livrés.',
    'settings.layout.help' => 'Le manifeste des panneaux ancrés ; écrit par le shell quand les panneaux se déplacent.',
    'settings.lintCommands.help' => 'Commande de lint post-édition par extension de fichier ({"php": "…", "js": false}) ; `php -l` est intégré.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}} : serveurs pour les diagnostics post-édition, les plans Read et l\'outil Lsp.',
    'settings.lspAutoDetect.help' => 'Démarrer le serveur de langage que l\'empreinte du projet nomme (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml ou setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) quand son binaire est sur PATH ; les entrées `lsp` manuelles l\'emportent par langage. Lancer un serveur exécute ce serveur et le code de build dans l\'arborescence ouverte, donc les empreintes ne démarrent des serveurs que dans les projets approuvés pour les hooks ; une racine non approuvée n\'en démarre aucun et enregistre l\'omission dans les avis de lancement.',
    'settings.maxCheckpoints.help' => 'Points de contrôle de tour vers lesquels /rewind peut revenir, par session ; les plus anciens sont élagués au-delà de cette valeur.',
    'settings.maxCostUsd.help' => 'Refuser de nouveaux tours quand la dépense rapportée par le fournisseur pour un lancement atteint ce montant en dollars US ; non défini = aucun plafond. /budget le modifie pour le lancement en cours uniquement.',
    'settings.maxOutputTokens.help' => 'Plafond de sortie par requête ; non défini n\'envoie aucun override et le défaut du fournisseur s\'applique.',
    'settings.maxToolSteps.help' => 'Appels fournisseur qu\'un tour peut effectuer ; non défini conserve le défaut du moteur.',
    'settings.mcp.enabled.help' => 'Démarrer les serveurs MCP nommés par le .mcp.json d\'un projet approuvé ; off n\'en démarre aucun et les surfaces signalent le lancement comme désactivé.',
    'settings.mcp.lazySchemaTokens.help' => 'Jetons de schéma qu\'un serveur MCP peut annoncer avant que ses outils ne délèguent à mcp_list/mcp_call ; 0 ne délègue jamais.',
    'settings.mcpResultCapBytes.help' => 'Nombre maximal d\'octets que la réponse d\'un outil MCP peut transmettre au modèle.',
    'settings.memory.autoConsolidate.help' => 'Enregistrer les faits durables des tours terminés dans la mémoire, et y intégrer le journal de compaction (la passe de rêve) ; chacune est un appel facturé.',
    'settings.memory.dreamIntervalSeconds.help' => 'Temps minimal entre deux passes de rêve pour un projet ; chaque passe est un tour facturé, en lecture seule.',
    'settings.memory.dreamProposeSkills.help' => 'Laisser la passe de rêve proposer des skills en brouillons dans ~/.candy-code/skills-proposed ; aucun n\'est actif tant que vous ne l\'acceptez pas via /skills.',
    'settings.memory.entryMaxBytes.help' => 'Longueur maximale de la ligne d\'index d\'une note avant qu\'elle ne soit affichée tronquée ; abaissée au budget de notes utilisateur si elle le dépasse.',
    'settings.memory.projectNoteMaxBytes.help' => 'Taille maximale d\'une note de mémoire de projet lors de son écriture dans le .candy-code/memory/ du dépôt.',
    'settings.memory.promptMaxBytes.help' => 'Budget en octets pour les lignes de notes de l\'index mémoire ; le budget de notes utilisateur est abaissé pour tenir dedans.',
    'settings.memory.promptMaxEntries.help' => 'Nombre maximal de notes que l\'index mémoire du prompt liste, les plus récentes d\'abord ; les notes utilisateur comptent dedans.',
    'settings.memory.userMaxBytes.help' => 'Budget en octets pour les lignes de portée utilisateur, à l\'intérieur du budget total.',
    'settings.memory.userMaxEntries.help' => 'Nombre maximal de vos notes inter-projets (portée utilisateur) listées en premier, à l\'intérieur du compteur de notes.',
    'settings.modelPrices.help' => 'USD par 1M de jetons par modèle ({"input": …, "output": …}), pour le total et le plafond de dépense.',
    'settings.models.help' => 'Le modèle à exécuter, par fournisseur ({"<provider>": "<model id>"}) ; non défini utilise le défaut du fournisseur.',
    'settings.mouse.help' => 'Signaler la souris à candy-code (clics, molette, sélection) ; off redonne au terminal son propre copy-on-select.',
    'settings.mouseClicks.help' => 'Les clics et glissements agissent sur ce qu\'ils touchent ; off conserve la molette et ignore les clics.',
    'settings.notices.transcriptLimit.help' => 'Nombre maximal d\'avertissements de lancement affichés comme lignes de transcription ; le reste est compté dans une ligne « et N de plus », et stderr les porte tous.',
    'settings.notify.help' => 'off, bell (BEL) ou osc9 (une notification de bureau) : envoyés quand un tour se termine et quand l\'agent attend une approbation.',
    'settings.paletteMru.help' => 'Nombre de lignes de palette récemment utilisées mémorisées et classées en premier ; 0 n\'en mémorise aucune.',
    'settings.parallelToolCalls.help' => 'Exécuter les appels d\'outils en lecture seule d\'un tour en parallèle.',
    'settings.parallelToolDeadlineSeconds.help' => 'Plafond en temps réel pour un lot d\'appels d\'outils dispatchés en parallèle.',
    'settings.permissionMode.help' => 'Comment les appels d\'outils sont filtrés. Jamais pris d\'un fichier projet.',
    'settings.permissionRules.help' => 'Règles allow / deny / ask ordonnées, comparées à chaque appel d\'outil. Le settings.json partagé d\'un projet approuvé peut contribuer des entrées deny / ask — uniquement restrictives.',
    'settings.permissions.autoAllowReadOnly.help' => 'Sous default et accept-edits, exécuter une ligne Bash composée uniquement de commandes en lecture seule (ls, cat, grep, git log, … ; pas de redirection fichier, pas de substitution, cd uniquement dans le projet) sans demander. Un projet ne peut que la désactiver.',
    'settings.permissions.autoStrikeLimit.help' => 'Sous auto, ce nombre d\'appels bloqués consécutifs d\'une catégorie transforme le suivant en question.',
    'settings.permissions.autoTotalLimit.help' => 'Sous auto, une fois ce nombre d\'appels bloqués dans une session, tout blocage supplémentaire vous demande.',
    'settings.pluginPaths.help' => 'Répertoires supplémentaires scannés pour les bundles de plugins au format Claude, en plus des deux racines installées ; une valeur peut nommer un bundle lui-même ou un conteneur de bundles. Niveau utilisateur uniquement — un checkout ne peut pas inscrire ses propres plugins.',
    'settings.promptCache.keepWarm.help' => 'Pings de réchauffement autorisés par période d\'inactivité ; 0 (défaut) = désactivé. Chaque ping renvoie le préfixe figé d\'une session inactive avec une ligne d\'instruction demandant une réponse d\'un caractère, afin que le fournisseur rafraîchisse son cache de prompt avant l\'expiration du TTL et que le prompt suivant ne pré-remplisse pas toute la conversation sans cache. Il ne se déclenche que là où le repli cacheTtl a décliné — sous son plancher ou avant son heure — sur le même tick/alarme que la surveillance du repli, jamais en milieu de tour, jamais plus d\'un à la fois, jamais au-delà de ce comptage par période. Ce sont des appels facturés à une session que personne ne surveille ; le plafond de dépense s\'applique toujours. Le comptage apparaît dans /usage sous `warm`.',
    'settings.promptCache.help' => 'Si les fournisseurs `vertex` et `bedrock` marquent les points de rupture du cache de prompt.',
    'settings.promptSuggestionHistory.help' => 'Messages récents (chacun tronqué à 2000 caractères) montrés à l\'appel de suggestion de prompt.',
    'settings.promptSuggestions.help' => 'Après chaque tour, demander au modèle de titre le message que vous êtes susceptible d\'envoyer ensuite et l\'afficher en gris dans la zone de saisie vide (→ l\'accepte).',
    'settings.provider.help' => 'Quel fournisseur LLM la session interroge ; chaque prompt est envoyé à son hôte.',
    'settings.providerRetryAttempts.help' => 'Appels par requête fournisseur en cas d\'échec transitoire (réseau, 5xx, 408, 429), le premier inclus ; 1 ne réessaie jamais.',
    'settings.providerRetryBaseBackoffMs.help' => 'Attente avant la première tentative d\'un appel fournisseur échoué ; chaque attente suivante double.',
    'settings.providers.help' => 'Définitions de fournisseurs par nom ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}) ; chaque entrée se superpose aux défauts de ce type. Niveau utilisateur uniquement : un projet ne doit jamais déplacer l\'endroit où votre identifiant est envoyé.',
    'settings.queueMode.help' => 'steer (l\'agent le lit à son étape suivante), followup (envoyé après le tour) ou interrupt (arrêter le tour à son étape suivante, puis envoyer). Tab met toujours en file.',
    'settings.readMaxBytes.help' => 'Plafond pour un appel Read ; la page ci-dessous est la taille à laquelle une lecture revient habituellement.',
    'settings.readPageBytes.help' => 'Octets qu\'une page Read peut contenir, numéros de ligne inclus, quelle que soit la valeur de `limit` demandée.',
    'settings.readPageLines.help' => 'Lignes que Read retourne quand l\'appel ne nomme pas de `limit`.',
    'settings.reasoningEffort.help' => 'Niveau de réflexion envoyé là où la paire le façonne : openai (série o et gpt-5, pas les builds -chat), anthropic et vertex (claude-3-7 et plus récents ; vertex répond sur ses deux bras claude et gemini), gemini (2.5 et plus récents), sglang (transmis sur chaque requête), bedrock (ids claude, comme budget de réflexion), codex et claude-code (niveaux nommés transmis au CLI) ; non défini ou non reconnu ne demande rien. `/effort` le définit et l\'efface.',
    'settings.redactToolOutput.help' => 'Désactivé par défaut : la sortie d\'outil stabilisée est enregistrée dans l\'historique et sessions.db exactement comme revenue. Quand activé, chaque résultat d\'outil passe par le même rédacteur qui protège la mémoire et `/share` une fois stabilisé — les identifiants reconnus deviennent `[REDACTED]` dans les octets persistés et dans ce que les tours ultérieurs rejouent au modèle (l\'outil lui-même s\'exécute toujours inchangé). Les champs image, document et usage passent intacts. `/export` n\'ajoute aucune censure propre : il imprime exactement ce qui a été stocké, donc tout ce qui a été sauvegardé avant l\'activation reste brut.',
    'settings.references.help' => 'Une liste de `[{"path": "…", "name": "…"}]` de répertoires hors de l\'espace de travail que Read, Grep, Glob et Ls peuvent aussi ouvrir, en lecture seule ; chacun est annoncé dans le bloc `<env>` avec une carte plafonnée de ce qu\'il contient. La geôle de l\'espace de travail est inchangée pour Write, Edit et Bash — une référence n\'élargit jamais ce qui peut être écrit. Niveau utilisateur uniquement : un dépôt checkouté ne peut pas ajouter une racine de lecture. Un chemin manquant ou non-répertoire, ou un chemin dans la racine de session, est refusé au lancement avec un avis.',
    'settings.repoMap.enabled.help' => 'Placer la carte de l\'emplacement du code (paquets et répertoires sources PSR-4) dans le prompt système.',
    'settings.repoMap.maxBytes.help' => 'Budget en octets pour chacune des deux sections de la carte du dépôt ; les entrées au-delà sont comptées, pas listées.',
    'settings.requireReadBeforeWrite.help' => 'Activé, `Edit`, un `Write` qui écrase un fichier existant, et une section `ApplyPatch` qui modifie, déplace ou supprime un fichier sont tous refusés tant que le modèle n\'a pas lu ce fichier dans cette session ; la création de nouveaux fichiers n\'est jamais bloquée. Désactivé par défaut : les fichiers que le modèle a lus restent protégés par la règle de modification sur disque dans les deux cas.',
    'settings.resumeCostWarnUsd.help' => 'Après une reprise obsolète, le premier prompt est retenu une fois quand le renvoi de l\'historique est estimé coûter au moins ce montant en dollars sans cache ; appuyez sur Entrée à nouveau pour envoyer quand même, ou /compact d\'abord. 0 désactive la retenue.',
    'settings.sandboxAllowedDomains.help' => 'Les hôtes que la geôle `allowlist` peut atteindre : noms simples (`example.com`), wildcards `*.example.com` et notations `host:port` (défaut : rien). Utilisé uniquement quand `bashSandbox` est `allowlist` sur Linux ; avec une liste VIDE, `allowlist` se comporte EXACTEMENT comme `no-network`. Le proxy de sortie autorise HTTP(S) et rien d\'autre — tout hôte non listé reçoit un 403, et le trafic non-HTTP (ssh, ports de base de données) échoue. Une entrée malformée est IGNORÉE à l\'application : une faute de frappe ne peut que réduire la permission, jamais l\'élargir. Niveau utilisateur uniquement : un dépôt checkouté ne doit pas ouvrir un trou dans la geôle dans laquelle il est arrivé. macOS applique `allowlist` comme `no-network` — le bras port loopback est un suivi planifié.',
    'settings.sandboxScope.help' => 'Quelles commandes hors du chemin d\'outil rejoignent la geôle `bashSandbox` : `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (défaut : aucune). Actives uniquement tant que `bashSandbox` n\'est pas `off` — la liste dit qui partage la geôle, jamais si une existe. Une entrée non reconnue se lit comme TOUS les périmètres (le plus strict, comme une valeur `bashSandbox` non reconnue), et l\'audit des paramètres le nomme. Une geôle qui ne peut pas démarrer refuse le travail plutôt que de l\'exécuter libre : les hooks script refusent, lint, format et test sautent avec la raison, et un serveur LSP ou MCP stdio en geôle n\'est pas démarré. Les entrées `lsp` et les entrées MCP de niveau utilisateur portent un opt-out `"sandbox": false` par serveur ; les opt-outs MCP de niveau projet sont ignorés.',
    'settings.screenReader.help' => 'Présentation pour les utilisateurs de lecteur d\'écran. Activé, l\'app abandonne la décoration qu\'un lecteur ne peut pas narrer — le spinner de l\'agent se fige sur une image statique, et les cadres en caractères de dessin, la sélection de menu en vidéo inverse seule et similaires cèdent la place au texte brut et à un signal sonore à chaque surface qui honore le basculement. Désactivé = le terminal peint comme d\'habitude. Votre propre paramètre d\'accessibilité, comme le mode vim de la zone de brouillon : un projet checkouté ne peut pas le modifier. S\'applique à la prochaine lecture après sauvegarde — en direct, sans rechargement.',
    'settings.rules.standingMaxBytes.help' => 'Budget en octets, encadré et échappé, pour les fichiers de règles insérés en entier dans chaque prompt ; une règle au-delà est nommée par une seule ligne de pointeur à la place.',
    'settings.scrollWheelLines.help' => 'Lignes de transcription qu\'un cran de molette fait défiler.',
    'settings.sd.apiKey.help' => 'Clé Bearer envoyée au serveur Stable Diffusion, s\'il en exige une ; préférez la forme d\'espace réservé `${VAR}` à une valeur littérale.',
    'settings.sd.baseUrl.help' => 'URL de base HTTP d\'un webui Stable Diffusion compatible AUTOMATIC1111 (`http://127.0.0.1:7860`) ; prompts, images et clé API sortent tous par là.',
    'settings.sd.defaultModel.help' => 'Id de modèle avec lequel les requêtes de génération commencent ; le serveur garde le choix pour lui quand non défini.',
    'settings.sd.presets.help' => 'Ensembles de paramètres nommés que le formulaire média propose ; la forme est propre au pipeline média, opaque à la couche de paramètres.',
    'settings.sd.savePattern.help' => 'Modèle de nom de fichier pour les médias sauvegardés ; les jetons `[date]`, `[time]`, `[seed]` et `[number]` se remplissent à la sauvegarde.',
    'settings.sd.timeoutSeconds.help' => 'Secondes qu\'une requête de génération peut s\'exécuter avant d\'être abandonnée ; la diffusion sur un GPU faible prend couramment des minutes.',
    'settings.secretEnvAllowlist.help' => 'Noms de variables en forme d\'identifiants (ou globs) que Bash, Grep et les hooks script héritent encore.',
    'settings.server.allowBypass.help' => 'Si les sessions serveur peuvent tourner en bypass-permissions ou dont-ask (identique à --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Noms d\'hôtes (ou host:port) auxquels le serveur répond, en plus des noms loopback et de ses propres adresses, p. ex. celui d\'un proxy inverse.',
    'settings.server.allowedIps.help' => 'IPs clients ou plages CIDR autorisées à se connecter, en plus du loopback ; tout autre est refusé 403 avant la connexion. Vide : aucun filtre d\'adresse.',
    'settings.server.allowedOrigins.help' => 'Origines de navigateur supplémentaires (http(s)://host[:port]) que le serveur accepte, en plus de la sienne.',
    'settings.server.askTimeoutSeconds.help' => 'Secondes qu\'une question de permission attend un client avant d\'être refusée ; 0 attend indéfiniment.',
    'settings.server.browseRoot.help' => 'Le répertoire auquel server.dirBrowse est confiné (identique à --browse-root) ; non défini = votre répertoire personnel.',
    'settings.server.dirBrowse.help' => 'Permettre aux clients connectés de lister les noms de répertoires sous server.browseRoot et d\'y démarrer des sessions (identique à --allow-dir-browse). Désactivé par défaut.',
    'settings.server.clientTools.help' => 'Permettre aux clients de portée Write d\'enregistrer des outils via tools.client.register afin que le modèle puisse appeler du code exécuté dans le client lui-même (outils client__*). Désactivé par défaut.',
    'settings.server.drainSeconds.help' => 'Secondes qu\'un serveur en arrêt attend pour les tours en cours avant de les annuler ; 0 s\'arrête immédiatement.',
    'settings.server.host.help' => 'L\'adresse sur laquelle `serve` se lie. Tout sauf loopback exige aussi --allow-remote au lancement.',
    'settings.server.maxConcurrentTurns.help' => 'Tours qu\'un serveur exécute simultanément à travers ses sessions ; un de plus est refusé occupé (réessayable).',
    'settings.server.maxOpenSessions.help' => 'Sessions qu\'un serveur garde ouvertes simultanément ; au-delà, la session inactive la moins récemment utilisée est libérée.',
    'settings.server.port.help' => 'Port auquel `serve` se lie ; 0 en choisit un libre.',
    'settings.server.trustedProxies.help' => 'IP ou CIDR dont le serveur accepte les en-têtes X-Forwarded-For / X-Forwarded-Proto.',
    'settings.serviceTier.help' => 'Voie premium envoyée là où la paire la façonne : openai demande `service_tier: "priority"` sur ses branches Chat et Responses, anthropic demande `speed: "fast"` (uniquement la famille claude-opus-5-5 GA et les familles research-preview claude-opus-5 / claude-opus-4-8, dont l\'en-tête beta requis est ajouté automatiquement) ; non défini ou non reconnu ne demande rien. Le mode rapide facture un premium qu\'aucune table de prix par modèle ne peut dériver : tant qu\'une paire à niveaux est active, ses tours sont inscrits au registre sans prix, jamais à un taux estimé. S\'applique au lancement et à chaque reconstruction de fournisseur ou de modèle.',
    'settings.sessionRetentionDays.help' => 'Chaque lancement supprime les sessions sans nom ni épinglette inactives depuis ce nombre de jours et indique lesquelles ; 0 (par défaut) conserve tout.',
    'settings.sessions.autoTitle.help' => 'Nommer chaque nouvelle session à partir de son premier tour via un appel au modèle de titre ; off la laisse sans nom jusqu\'à /rename.',
    'settings.sessions.awayRecap.help' => 'Quand le terminal signale un retour de focus après trois minutes ou plus d\'absence, afficher un récapitulatif de l\'endroit où la session s\'est arrêtée (un appel au modèle de titre par absence) ; off laisse le retour silencieux. `/recap` en demande un à tout moment.',
    'settings.skills.listingMaxBytes.help' => 'Budget en octets pour la liste complète des skills dans le prompt système ; les skills au-delà se résument en une ligne « N more skills ».',
    'settings.skills.pathNudges.help' => 'Quand un outil touche un fichier couvert par un skill à portée de chemin, rappeler au modèle l\'existence de ce skill, une fois par skill.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2} : une commande shell dont la sortie alimente la barre de statut, réexécutée toutes les refreshSeconds (2 à 3600, défaut 2). Elle reçoit la session sous forme d\'un document JSON sur stdin (session_id, cwd, model, workspace, version, cost, plus les extras candy_code) ; une commande qui ne lit jamais stdin s\'exécute quand même.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Secondes qu\'un serveur de streaming connecté peut prendre pour envoyer ses en-têtes de réponse ; jamais un délai total de requête.',
    'settings.streamIdleTimeoutSeconds.help' => 'Secondes qu\'une lecture d\'une réponse en streaming peut attendre des octets avant que la connexion soit déclarée morte ; par lecture, jamais un total.',
    'settings.subagentMaxActive.help' => 'Exécutions déléguées qu\'une session peut mener de front, tous niveaux confondus, membres et agents d\'arrière-plan comptés ; au-delà, un appel `Task` est refusé. Non défini — le défaut — ou 0 ne fixe aucun plafond.',
    'settings.subagentMaxConcurrent.help' => 'Appels `Task` d\'un même lot exécutés de front (les autres attendent un créneau libre), et la largeur de chaque pool d\'agents. Non défini — le défaut — ou 0 ne fixe aucun plafond.',
    'settings.subagentMaxDepth.help' => 'Niveaux sous la session qu\'une exécution déléguée peut atteindre ; une exécution au dernier niveau n\'a pas de `Task`. 1 empêche les sous-agents de déléguer davantage.',
    'settings.subagentMaxTurns.help' => 'Plafond d\'étapes pour un sous-agent — une délégation `Task`, une étape de workflow ou une exécution `executeAgents` — dont le preset ne déclare pas de `maxTurns`.',
    'settings.subagentModel.help' => 'Modèle sur lequel un sous-agent délégué s\'exécute quand son preset indique `inherit` ; non défini suit le modèle de la session.',
    'settings.summaryModel.help' => 'Modèle qui rédige les résumés de compaction ; non défini utilise le modèle de la conversation, ce qui réutilise le cache de prompt.',
    'settings.symbolMap.enabled.help' => 'Placer la carte de repo symbolique classée dans le prompt système, capturée une fois par session.',
    'settings.temperature.help' => 'Température d\'échantillonnage que le fournisseur `custom` envoie quand une requête n\'en nomme aucune.',
    'settings.terminalBackground.help' => 'Ce que le thème adaptatif suppose derrière le texte : auto interroge le terminal (OSC 11, puis COLORFGBG) ; light ou dark l\'affirme directement.',
    'settings.testCommand.help' => 'Commande shell qui exécute les tests du projet, à la racine du projet (`composer test`, `pytest -q`) ; ce que `autoTest` lance.',
    'settings.theme.help' => 'Thème de couleurs ; /theme et la palette le modifient en direct. Les thèmes personnalisés se chargent depuis des fichiers JSON sous ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Budget de tokens de réflexion : `thinkingConfig` de Gemini sur le fournisseur `vertex` ; réflexion étendue sur le fournisseur `anthropic`, où le plancher de l\'API Messages est 1024 (0 ou non défini signifie désactivé sur les deux branches). Les tokens de réflexion sont facturés en sortie.',
    'settings.titleModel.help' => 'Modèle qui nomme les sessions et rédige les suggestions de prompt ; non défini utilise le défaut auxiliaire bon marché du type de fournisseur avant le modèle de bloc.',
    'settings.transcriptJsonl.help' => 'Miroir de chaque transcript validé dans un journal JSONL en append-only sous `~/.candy-code/transcripts/<project>/` (fichiers 0600), et fournir aux scripts de hook une clé stdin `transcript_path` pointant dessus. Le journal contient la conversation brute et croît sans limite ; lu au lancement, donc un changement s\'applique au prochain démarrage.',
    'settings.toolInstructionCapBytes.help' => 'La plus grande taille d\'un corps CLAUDE.md/AGENTS.md régissant qu\'un résultat Edit, Write ou ApplyPatch peut porter ; le reste est coupé avec un marqueur.',
    'settings.toolOutputCapBytes.help' => 'Le plus grand nombre d\'octets qu\'un résultat Bash, Grep, Glob, Lsp ou WebFetch peut remettre au modèle ; ce qui est coupé est sauvegardé dans un fichier que le résultat nomme.',
    'settings.toolOutputPreviewLines.help' => 'Lignes d\'un résultat d\'outil replié affichées dans le transcript ; Ctrl+O déplie le reste.',
    'settings.toolSpillCaptureBytes.help' => 'Le plus grand volume de sortie d\'une commande Bash (par flux) retenu en mémoire et sauvegardé dans le fichier de déversement quand le résultat est coupé ; jamais en dessous du plafond de sortie.',
    'settings.toolSpillMinCapBytes.help' => 'Le plus petit plafond de résultat auquel un résultat d\'outil coupé est sauvegardé dans un fichier ; en dessous, la coupure est annoncée et le reste est perdu.',
    'settings.toolSpillWindowPercent.help' => 'La plus grande part de la fenêtre de contexte qu\'un résultat d\'outil peut prendre ; au-delà, le résultat est sauvegardé dans un fichier et le modèle voit son début et sa fin.',
    'settings.trustedProjectCommands.help' => 'Racines de projet dont les commandes slash peuvent exécuter des blocs shell !`cmd`.',
    'settings.trustedProjectHooks.help' => 'Racines de projet dont .candy-code/hooks.yaml peut s\'exécuter.',
    'settings.trustedProjectMcp.help' => 'Racines de projet dont les serveurs .mcp.json peuvent être lancés.',
    'settings.trustedProjectSettings.help' => 'Racines de projet dont .candy-code/settings*.json peut définir les clés de niveau projet.',
    'settings.turnIdleTimeoutSeconds.help' => 'Secondes qu\'un tour en cours peut durer sans aucun progrès avant d\'être arrêté comme bloqué ; temps d\'inactivité, jamais un total.',
    'settings.ui.imageRenderMode.help' => 'Comment les images générées sont dessinées dans le terminal ; `auto` choisit le meilleur protocole que le terminal signale.',
    'settings.ui.mediaDisplayOverrides.help' => 'Ajustements d\'affichage par mode de rendu (plafonds de taille, solutions de repli) ; les clés sont les mots de mode de rendu, les valeurs les réglages d\'affichage.',
    'settings.vimMode.help' => 'Édition NORMAL/INSERT dans la zone de brouillon (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, objets de texte di" da( ciw, compteurs 3dd d2w) : déplacements, modification, suppression et yank en NORMAL, saisie verbatim en INSERT. Un mode, pas des raccourcis — il n\'apparaît jamais dans /keys. S\'applique à la frappe suivante après sauvegarde.',
    'settings.voice.apiKey.help' => 'Clé Bearer envoyée au point de terminaison de transcription, s\'il en exige une ; préférer la forme d\'espace réservé `${VAR}` à une valeur littérale.',
    'settings.voice.baseUrl.help' => 'URL de base HTTP d\'un point de terminaison de transcription compatible OpenAI (un `/v1` final est conservé) ; la prise enregistrée sort par là et nulle part ailleurs. Pas de défaut : la saisie vocale reste OFF tant que ce n\'est pas défini dans le niveau utilisateur.',
    'settings.voice.language.help' => 'Code BCP-47 (`en`, `de`) forçant la langue de transcription ; non défini laisse le point de terminaison la détecter.',
    'settings.voice.maxSeconds.help' => 'Plafond dur en secondes d\'un enregistrement (5-600, défaut 120). Le plafond est transmis à l\'argument de l\'enregistreur, donc une prise orpheline s\'arrête d\'elle-même.',
    'settings.voice.model.help' => 'Identifiant de modèle envoyé avec chaque requête de transcription ; `whisper-1` répond sur les points de terminaison compatibles OpenAI.',
    'settings.watchFiles.help' => 'Envoyer un prompt quand un fichier sauvegardé contient un commentaire finissant par AI! (faire un changement) ou AI? (répondre à une question) ; les commentaires AI simples accompagnent comme contexte. Interrogé pendant l\'inactivité du chat ; seuls les commentaires sauvegardés après le lancement se déclenchent, chacun une fois. Sessions terminal uniquement : l\'observateur tourne dans le processus terminal, donc une session hébergée par `candy-code serve` ne surveille pas les fichiers.',
    'settings.webFetchMaxBytes.help' => 'Le plus grand volume d\'un corps récupéré retenu en mémoire ; une limite mémoire, le plafond de sortie est ce qui atteint le modèle.',
    'settings.webFetchTimeoutSeconds.help' => 'Secondes qu\'une lecture de socket WebFetch peut stagner avant que la récupération échoue.',
    'settings.webSearchBackend.help' => 'Quel service de recherche WebSearch interroge : `searxng` (le défaut) envoie chaque requête au `webSearchEndpoint` configuré ; `brave`, `tavily` et `exa` appellent l\'hôte fixe de ce service et chacun a besoin de sa clé API dans l\'environnement (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), sans moyen de les pointer vers une autre URL.',
    'settings.webSearchEndpoint.help' => 'URL de recherche d\'une instance SearXNG de confiance (`https://searx.example.org/search`) ; chaque requête WebSearch y est envoyée.',
    'settings.webSearchMaxResults.help' => 'Résultats qu\'un digest WebSearch liste, chacun un titre, une URL et un extrait.',
    'settings.webSearchTimeoutSeconds.help' => 'Secondes qu\'une requête de recherche peut prendre.',
    'settings.webhooks.help' => 'Carte du nom de hook vers {secret, prompt, permissionMode?, rate?} ; POST /api/hooks/{name} insère ensuite le corps (échappé comme non fiable) dans le prompt et démarre une session d\'arrière-plan. Vide (défaut) ne monte rien. rate est N livraisons par minute par adresse, et par hook au total. bypass-permissions est refusé pour les hooks au lancement ; un hook sans mode s\'exécute dans le plus strict du mode serveur et du défaut. Une ligne peut aussi nommer signature : {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?} : la route vérifie alors un HMAC-SHA256 du corps brut (sha256=<hex>) avec le secret de la ligne via l\'en-tête de signature, à la place du secret d\'en-tête personnalisé, car GitHub ne peut pas envoyer d\'en-têtes personnalisés ; les signatures échouées alimentent le même verrouillage par hook, et un id de livraison déjà vu (X-GitHub-Delivery par défaut pour le schéma GitHub ; le deliveryHeader configuré pour un générique) répond {"ok": true, "duplicate": true} sans démarrer une seconde session.',
    'settings.webhooksOut.help' => 'Carte du nom de point de terminaison vers {url, secret, events} ; events est une liste non vide tirée de turn.completed, session.ended, permission.asked et schedule.fired. Vide (défaut) n\'ouvre aucune sortie. Lu depuis le niveau USER uniquement — une config de projet ou de bundle ne peut jamais ajouter un point de terminaison sortant. url doit être https, ou http uniquement quand son hôte littéral est localhost ou une adresse de bouclage, et ne porte jamais d\'userinfo ; secret est d\'au moins 16 caractères et signe chaque livraison par HMAC-SHA256 comme X-Candy-Code-Signature (sha256=<hex> sur le corps exact) associé à X-Candy-Code-Timestamp. La livraison est asynchrone sur la boucle d\'événements — les envois n\'attendent jamais une réponse : une limite de connexion de 2 secondes et un plafond réseau de 10 secondes par POST bornent chaque livraison (limites de webhook, pas un délai de requête LLM), les transports échoués et les réponses 5xx montent une échelle de reprise 2/8/30 secondes, les réponses 4xx et les redirections sont définitives dès la première fois car les redirections sont refusées plutôt que suivies, et une file bornée de 128 livraisons en vol écarte les nouveaux envois en cas de débordement plutôt que de faire croître la mémoire. Lu au lancement ; modifier la carte prend effet au redémarrage.',
    'settings.webhooksOut.refuse' => 'webhooksOut dans la config utilisateur est inutilisable : {reason}. Refus de démarrer plutôt que de livrer à un point de terminaison à moitié vérifié — corriger la carte, ou retirer la clé pour tourner sans webhooks sortants.',
    // --- end settings help ---

    // --- begin tui.window (P-TABS.a) ---
