    'tui.window.overflow' => '‹{count}›',
    'tui.window.unnamed' => 'fenêtre',
    'tui.window.summary' => '{sessions} fenêtres · {attention} nécessitent une attention',
    'tui.window.summary.none' => 'aucune fenêtre ouverte',
    // --- end tui.window (P-TABS.a) ---

    // --- begin tui.window.title (P-TABS.g) ---
