    // src/App/App.php's deck choke (windowList/afterDeckChange).
    'tui.window.title.plain' => 'candy-code',
    'tui.window.title.attention' => 'candy-code — {waiting} en attente · {running} en cours',
    'tui.window.attention.waiting' => '{name} attend une réponse',
    'tui.window.attention.unseen' => '{name} a terminé pendant votre absence',
    // --- end tui.window.title (P-TABS.g) ---

    // --- begin tui.sessions (P-TABS.c) ---
    // Strings of the vertical sessions pane in
    // src/Tui/Components/SessionsPane.php. Same census law as the block
    // above (TuiLangTest): quoted keys ride the source, source literals
    // live here.
    'tui.sessions.new' => '＋ Nouvelle session',
    'tui.sessions.title' => 'Sessions',
    'tui.sessions.unnamed' => 'session',
    'tui.sessions.agents' => '{count} agents',
    // --- end tui.sessions (P-TABS.c) ---

    // --- session.import (C-SES-7.a: the importer core) ---
    'session.import.notice' => 'Transcript {format} importé — matériau de référence non fiable : son activité d\'outils est consignée en texte, jamais rejouée.',
    'session.import.refusal.not_readable' => 'import : {path} n\'est pas un fichier lisible, rien n\'a été importé',
    'session.import.refusal.source_shrank' => 'import : la source contient désormais moins de lignes de transcript que la dernière importation enregistrée, et un transcript rétréci est refusé plutôt que réécrit',
    'session.import.refusal.too_large' => 'import : le transcript fait {bytes} octets, au-delà de la limite de {max} octets',
    'session.import.refusal.too_many_items' => 'import : le transcript contient plus de lignes que la limite de {max} lignes',
    'session.import.refusal.unknown_format' => 'import : le fichier ne correspond à un transcript CandyCode, Claude Code, Codex ou OpenCode, rien n\'a été deviné',
    'session.import.refusal.unsupported_shape' => 'import : la forme du transcript n\'est pas reconnue ({detail}) ; les formats inconnus sont refusés, jamais devinés',
    // --- end session.import ---

    // --- begin tui.diffreview (C-TUI-2.d: diff-review core) ---
    'tui.diffreview.title' => 'Fichiers modifiés {steps} checkpoint(s) en arrière',
    'tui.diffreview.turn_suffix' => ' · ce tour uniquement',
    'tui.diffreview.empty' => '(aucun changement depuis ce checkpoint)',
    'tui.diffreview.omitted' => '… {lines} lignes omises à la limite d\'affichage',
    'tui.diffreview.hints' => '↑/↓ fichier · PgUp/PgDn corps · -/+ base · t ce tour · Esc fermer',
    // --- end tui.diffreview (C-TUI-2.d) ---
    // --- begin commit (C-AGT-6.a: /commit builtin) ---
    // Strings of the manual whole-tree commit: src/Host/Commands/
    // CommitHostCommand.php and builtin-commands/2850-commit.php. The drafting
    // itself rides CommitMessageWriter, shared with the `turn`-mode auto-commit.
    'cmd.commit.description' => 'Committer tous les fichiers modifiés, rédiger le message si aucun n\'est fourni',
    'cmd.commit.hint' => '<message>',
    'host.commit.nothing' => 'Rien à committer : l\'arbre de travail est propre.',
    'host.commit.not_repo' => '/commit non exécuté : ce projet n\'est pas un arbre de travail git.',
    'host.commit.committed' => 'Committed {sha} ({subject}) : {files} inclus ; /undo peut annuler.',
    'host.commit.failed' => 'Rien n\'a été committé : {reason}.',
    'host.commit.no_reason' => 'aucune raison donnée',
    // --- end commit (C-AGT-6.a) ---
    // --- tui.wizard (C-TUI-5.d: first-run wizard core) ---
    // Census law (TuiLangTest): every quoted tui. key in src lives here and
    // every key here is asked by src. Strings of the two-step provider setup
    // in src/Tui/FirstRunWizard/FirstRunWizard.php.
    'tui.wizard.title' => 'Bienvenue dans candy-code — configurons un fournisseur.',
